css:
.acr-photo {
  /* re-theme with these four */
  --acr-photo-bg: oklch(0.185 0.006 65);
  --acr-photo-panel: oklch(0.222 0.007 65);
  --acr-photo-ink: oklch(0.93 0.012 80);
  --acr-photo-accent: oklch(0.8 0.135 72);
  /* derived */
  --acr-photo-raise: color-mix(in oklch, var(--acr-photo-panel) 86%, var(--acr-photo-ink));
  --acr-photo-line: color-mix(in oklch, var(--acr-photo-ink) 9%, transparent);
  --acr-photo-line2: color-mix(in oklch, var(--acr-photo-ink) 16%, transparent);
  --acr-photo-hover: color-mix(in oklch, var(--acr-photo-ink) 6%, transparent);
  --acr-photo-mute: color-mix(in oklch, var(--acr-photo-ink) 62%, var(--acr-photo-bg));
  --acr-photo-faint: color-mix(in oklch, var(--acr-photo-ink) 40%, var(--acr-photo-bg));
  --acr-photo-acc-soft: color-mix(in oklch, var(--acr-photo-accent) 16%, transparent);
  --acr-photo-acc-ink: color-mix(in oklch, var(--acr-photo-accent) 22%, oklch(0.18 0.02 60));
  --acr-photo-ease: cubic-bezier(.2, .8, .2, 1);
  --acr-photo-out: cubic-bezier(.16, 1, .3, 1);
  --acr-photo-spring: linear(0, 0.12 6%, 0.46 14%, 0.86 24%, 1.04 32%, 1.07 38%, 1.03 48%, 0.996 62%, 1);
  --acr-photo-mono: ui-monospace, Menlo, monospace;

  position: relative; width: 100%; height: var(--acr-photo-h, 680px); box-sizing: border-box;
  container-type: inline-size; container-name: acr-photo; overflow: clip; isolation: isolate;
  display: grid; grid-template-rows: auto minmax(0, 1fr) auto;
  border-radius: 14px; background: var(--acr-photo-bg); color: var(--acr-photo-ink); color-scheme: dark;
  accent-color: var(--acr-photo-accent);
  font: 12.5px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased; -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--acr-photo-accent); outline-offset: 2px; }
  & button, & input { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & button:disabled { cursor: not-allowed; opacity: .38; }
  & h2, & h3, & p, & ol { margin: 0; padding: 0; }
  & ol { list-style: none; }
  & [hidden] { display: none !important; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { display: inline-grid; place-items: center; min-width: 17px; height: 17px; padding: 0 4px; border-radius: 4px; font: 600 10px/1 var(--acr-photo-mono); color: var(--acr-photo-mute); background: var(--acr-photo-hover); box-shadow: inset 0 0 0 1px var(--acr-photo-line2); }
  & h3 { display: flex; align-items: center; gap: 8px; font-size: 10.5px; font-weight: 680; letter-spacing: .11em; text-transform: uppercase; color: var(--acr-photo-faint); }
  & h3 > span:not([role]) { margin-left: auto; font-weight: 500; letter-spacing: 0; text-transform: none; font-variant-numeric: tabular-nums; }
}

/* ── top bar ─────────────────────────────────────────── */
.acr-photo .acr-photo-top {
  display: flex; align-items: center; gap: 14px; padding: 9px 12px 9px 16px; min-width: 0;
  border-bottom: 1px solid var(--acr-photo-line); background: color-mix(in oklch, var(--acr-photo-bg) 70%, var(--acr-photo-panel));
}
.acr-photo .acr-photo-brand { display: flex; align-items: center; gap: 8px; font-weight: 720; letter-spacing: -.01em; font-size: 13.5px;
  & svg { width: 20px; height: 20px; color: var(--acr-photo-accent); }
}
.acr-photo .acr-photo-file { display: flex; align-items: baseline; gap: 10px; min-width: 0; padding-left: 14px; border-left: 1px solid var(--acr-photo-line);
  & b { font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & span { font: 11px var(--acr-photo-mono); color: var(--acr-photo-faint); white-space: nowrap; font-variant-numeric: tabular-nums; }
}
.acr-photo .acr-photo-acts { margin-left: auto; display: flex; align-items: center; gap: 6px; flex: none; }
.acr-photo .acr-photo-ib {
  display: grid; place-items: center; width: 30px; height: 30px; border-radius: 8px; color: var(--acr-photo-mute);
  transition: background-color .18s, color .18s, transform .3s var(--acr-photo-spring);
  &:hover:not(:disabled) { background: var(--acr-photo-hover); color: var(--acr-photo-ink); }
  &:active:not(:disabled) { transform: scale(.9); }
}
.acr-photo .acr-photo-seg {
  display: inline-flex; padding: 2px; gap: 2px; border-radius: 9px; background: var(--acr-photo-hover); box-shadow: inset 0 0 0 1px var(--acr-photo-line);
  & button { height: 26px; padding: 0 10px; border-radius: 7px; font-size: 11.5px; font-weight: 560; color: var(--acr-photo-mute); transition: background-color .2s, color .2s; }
  & button:hover { color: var(--acr-photo-ink); }
  & button[aria-checked="true"] { background: var(--acr-photo-raise); color: var(--acr-photo-ink); box-shadow: 0 1px 2px oklch(0 0 0 / .4), inset 0 0 0 1px var(--acr-photo-line2); }
}
.acr-photo .acr-photo-primary {
  display: inline-flex; align-items: center; gap: 7px; height: 30px; padding: 0 13px; border-radius: 8px;
  background: var(--acr-photo-accent); color: var(--acr-photo-acc-ink); font-weight: 650;
  box-shadow: inset 0 1px 0 oklch(1 0 0 / .35), 0 1px 2px oklch(0 0 0 / .4);
  transition: filter .2s, transform .35s var(--acr-photo-spring);
  &:hover { filter: brightness(1.07); }
  &:active { transform: scale(.95); }
}
.acr-photo .acr-photo-ghost { height: 30px; padding: 0 12px; border-radius: 8px; color: var(--acr-photo-mute); &:hover { background: var(--acr-photo-hover); color: var(--acr-photo-ink); } }

/* ── body grid ───────────────────────────────────────── */
.acr-photo .acr-photo-body {
  min-height: 0; display: grid; grid-template-columns: 232px minmax(0, 1fr) 296px; grid-template-rows: minmax(0, 1fr);
  grid-template-areas: "left stage right";
}
.acr-photo .acr-photo-left, .acr-photo .acr-photo-right {
  min-height: 0; overflow-y: auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: var(--acr-photo-line2) transparent;
  background: var(--acr-photo-panel); display: flex; flex-direction: column;
}
.acr-photo .acr-photo-left { grid-area: left; border-right: 1px solid var(--acr-photo-line); }
.acr-photo .acr-photo-right { grid-area: right; border-left: 1px solid var(--acr-photo-line); }
.acr-photo .acr-photo-sec { padding: 14px 14px 16px; border-bottom: 1px solid var(--acr-photo-line); display: grid; gap: 10px; }

/* looks */
.acr-photo .acr-photo-looks { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.acr-photo .acr-photo-look {
  display: grid; gap: 5px; text-align: left; border-radius: 9px; padding: 4px 4px 6px; font-size: 11.5px; color: var(--acr-photo-mute);
  transition: background-color .2s, color .2s;
  animation: acr-photo-rise .5s var(--acr-photo-out) both; animation-delay: calc(var(--i, 0) * 38ms);
  & canvas { width: 100%; aspect-ratio: 3 / 2; height: auto; border-radius: 6px; display: block; box-shadow: 0 0 0 1px var(--acr-photo-line); transition: box-shadow .25s, transform .35s var(--acr-photo-spring); }
  & span { padding: 0 2px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  &:hover { background: var(--acr-photo-hover); color: var(--acr-photo-ink); & canvas { transform: scale(1.03); } }
  &[aria-selected="true"] { color: var(--acr-photo-ink); & canvas { box-shadow: 0 0 0 2px var(--acr-photo-accent), 0 4px 14px oklch(0 0 0 / .4); } & span::before { content: "● "; color: var(--acr-photo-accent); font-size: 8px; vertical-align: 2px; } }
}
@keyframes acr-photo-rise { from { opacity: 0; transform: translateY(6px) scale(.97); } }

/* history */
.acr-photo .acr-photo-hist { display: grid; gap: 1px; counter-reset: acr-photo-h; }
.acr-photo .acr-photo-hist li { display: contents; }
.acr-photo .acr-photo-hist button {
  width: 100%; display: grid; grid-template-columns: 14px minmax(0, 1fr) auto; align-items: center; gap: 8px; padding: 5px 8px; border-radius: 7px; text-align: left;
  color: var(--acr-photo-mute); font-size: 12px; transition: background-color .15s, color .15s, opacity .2s;
  & i { width: 7px; height: 7px; border-radius: 50%; box-shadow: inset 0 0 0 1.5px currentColor; justify-self: center; }
  & span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & small { font: 10.5px var(--acr-photo-mono); color: var(--acr-photo-faint); font-variant-numeric: tabular-nums; }
  &:hover { background: var(--acr-photo-hover); color: var(--acr-photo-ink); }
  &[aria-current="step"] { background: var(--acr-photo-acc-soft); color: var(--acr-photo-ink); & i { background: var(--acr-photo-accent); box-shadow: none; } }
  &.is-future { opacity: .45; & span { text-decoration: line-through; text-decoration-color: var(--acr-photo-faint); } }
}
.acr-photo .acr-photo-hist li.is-new button { animation: acr-photo-slide .45s var(--acr-photo-out); }
@keyframes acr-photo-slide { from { opacity: 0; transform: translateX(-8px); background: var(--acr-photo-acc-soft); } }

/* ── stage ───────────────────────────────────────────── */
.acr-photo .acr-photo-stage { grid-area: stage; min-width: 0; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr) auto auto; gap: 10px; padding: 10px 16px 12px;
  background: radial-gradient(120% 90% at 50% 40%, color-mix(in oklch, var(--acr-photo-bg) 80%, var(--acr-photo-ink) 3%), var(--acr-photo-bg));
}
.acr-photo .acr-photo-bar { display: flex; align-items: center; gap: 10px; min-width: 0; }
.acr-photo .acr-photo-exif { margin-inline: auto; font: 11px var(--acr-photo-mono); color: var(--acr-photo-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-variant-numeric: tabular-nums; }
.acr-photo .acr-photo-chip {
  display: inline-flex; align-items: center; gap: 6px; height: 26px; padding: 0 6px 0 9px; border-radius: 7px; font-size: 11.5px; color: var(--acr-photo-mute); white-space: nowrap;
  box-shadow: inset 0 0 0 1px var(--acr-photo-line); transition: background-color .18s, color .18s, box-shadow .18s;
  & svg { width: 14px; height: 14px; }
  &:hover { color: var(--acr-photo-ink); background: var(--acr-photo-hover); }
  &[aria-pressed="true"] { color: var(--acr-photo-accent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--acr-photo-accent) 55%, transparent); background: var(--acr-photo-acc-soft); }
}
.acr-photo .acr-photo-view { container-type: size; min-height: 0; display: grid; place-items: center; }
.acr-photo .acr-photo-frame {
  position: relative; width: min(100cqw, 150cqh); aspect-ratio: 3 / 2; border-radius: 3px; overflow: hidden;
  box-shadow: 0 0 0 1px oklch(0 0 0 / .5), 0 18px 40px -12px oklch(0 0 0 / .7), 0 2px 6px oklch(0 0 0 / .35);
  --s: 50%;
}
.acr-photo .acr-photo-canvas { display: block; width: 100%; height: 100%; }
.acr-photo .acr-photo-tag {
  position: absolute; top: 10px; padding: 3px 8px; border-radius: 99px; font-size: 10.5px; font-weight: 650; letter-spacing: .06em; text-transform: uppercase;
  background: oklch(0.15 0.01 60 / .62); color: oklch(0.96 0.01 80); backdrop-filter: blur(6px); pointer-events: none;
  transition: opacity .3s, transform .4s var(--acr-photo-out);
}
.acr-photo .acr-photo-tag-b { left: 10px; }
.acr-photo .acr-photo-tag-a { right: 10px; }
.acr-photo .acr-photo-split {
  position: absolute; top: 0; bottom: 0; left: var(--s); width: 28px; margin-left: -14px; cursor: ew-resize; touch-action: none;
  display: grid; place-items: center; transition: opacity .3s;
  &::before { content: ""; position: absolute; top: 0; bottom: 0; left: 50%; width: 2px; margin-left: -1px; background: oklch(0.98 0.01 80 / .92); box-shadow: 0 0 0 1px oklch(0 0 0 / .18), 0 0 12px oklch(0 0 0 / .4); }
  &:focus-visible { outline: none; & .acr-photo-knob { outline: 2px solid var(--acr-photo-accent); outline-offset: 2px; } }
}
.acr-photo .acr-photo-knob {
  position: relative; display: grid; place-items: center; width: 30px; height: 30px; border-radius: 50%; color: oklch(0.2 0.01 60);
  background: oklch(0.98 0.01 80); box-shadow: 0 2px 10px oklch(0 0 0 / .45); transition: transform .35s var(--acr-photo-spring);
  & svg { width: 15px; height: 15px; stroke-width: 2; }
}
.acr-photo .acr-photo-split:hover .acr-photo-knob, .acr-photo .acr-photo-split.is-drag .acr-photo-knob { transform: scale(1.12); }
.acr-photo[data-cmp="after"] .acr-photo-split, .acr-photo[data-cmp="before"] .acr-photo-split { opacity: 0; pointer-events: none; }
.acr-photo[data-cmp="after"] .acr-photo-tag-b, .acr-photo[data-cmp="before"] .acr-photo-tag-a { opacity: 0; transform: translateY(-4px); }
.acr-photo[data-cmp="split"] .acr-photo-tag-b { opacity: clamp(0, calc((var(--sn, .5) - .12) * 8), 1); }
.acr-photo[data-cmp="split"] .acr-photo-tag-a { opacity: clamp(0, calc((.88 - var(--sn, .5)) * 8), 1); }

/* filmstrip */
.acr-photo .acr-photo-strip { display: flex; justify-content: center; gap: 8px; }
.acr-photo .acr-photo-film {
  position: relative; display: grid; gap: 4px; padding: 3px; border-radius: 8px; text-align: left; font-size: 11px; color: var(--acr-photo-faint);
  transition: color .2s, background-color .2s;
  & canvas { width: 84px; height: 56px; display: block; border-radius: 5px; box-shadow: 0 0 0 1px var(--acr-photo-line); transition: box-shadow .25s, filter .25s; filter: saturate(.8) brightness(.85); }
  & span { padding: 0 2px; white-space: nowrap; }
  & em { position: absolute; top: 7px; right: 7px; width: 6px; height: 6px; border-radius: 50%; background: var(--acr-photo-accent); box-shadow: 0 0 0 2px oklch(0 0 0 / .35); }
  &:hover { color: var(--acr-photo-ink); & canvas { filter: none; } }
  &[aria-selected="true"] { color: var(--acr-photo-ink); & canvas { filter: none; box-shadow: 0 0 0 2px var(--acr-photo-ink); } }
}
.acr-photo .acr-photo-keys { display: flex; justify-content: center; flex-wrap: wrap; gap: 4px 14px; font-size: 11px; color: var(--acr-photo-faint);
  & span { display: inline-flex; align-items: center; gap: 5px; white-space: nowrap; }
}

/* ── right panel ─────────────────────────────────────── */
.acr-photo .acr-photo-histwrap { position: relative; height: 92px; border-radius: 8px; overflow: hidden; background: oklch(0.15 0.005 65); box-shadow: inset 0 0 0 1px var(--acr-photo-line);
  & canvas { width: 100%; height: 100%; display: block; }
}
.acr-photo .acr-photo-clipdot { position: absolute; top: 6px; width: 0; height: 0; border: 5px solid transparent; opacity: .35; transition: opacity .2s, filter .2s;
  &.is-on { opacity: 1; filter: drop-shadow(0 0 4px currentColor); }
}
.acr-photo .acr-photo-clipdot-l { left: 6px; border-top-color: oklch(0.72 0.12 245); color: oklch(0.72 0.12 245); }
.acr-photo .acr-photo-clipdot-h { right: 6px; border-top-color: oklch(0.7 0.19 28); color: oklch(0.7 0.19 28); }
.acr-photo .acr-photo-histread { display: flex; justify-content: space-between; font: 10.5px var(--acr-photo-mono); color: var(--acr-photo-faint); font-variant-numeric: tabular-nums;
  & b { color: var(--acr-photo-mute); font-weight: 500; }
}
.acr-photo .acr-photo-chans { margin-left: auto; display: inline-flex; gap: 2px; letter-spacing: 0;
  & button { width: 30px; height: 20px; border-radius: 5px; font: 650 10px var(--acr-photo-mono); color: var(--acr-photo-faint); transition: background-color .15s, color .15s; }
  & button:hover { color: var(--acr-photo-ink); }
  & button[aria-checked="true"] { background: var(--acr-photo-hover); color: var(--acr-photo-ink); box-shadow: inset 0 0 0 1px var(--acr-photo-line2); }
  & [data-ch="r"][aria-checked="true"] { color: oklch(0.72 0.17 25); }
  & [data-ch="g"][aria-checked="true"] { color: oklch(0.78 0.16 145); }
  & [data-ch="b"][aria-checked="true"] { color: oklch(0.72 0.13 250); }
}
.acr-photo .acr-photo-curvewrap { position: relative; aspect-ratio: 1.25; border-radius: 8px; overflow: hidden; background: oklch(0.155 0.005 65); box-shadow: inset 0 0 0 1px var(--acr-photo-line);
  & canvas { width: 100%; height: 100%; display: block; cursor: crosshair; touch-action: none; }
  & canvas:focus-visible { outline-offset: -2px; }
}
.acr-photo .acr-photo-hint { font-size: 11px; color: var(--acr-photo-faint); display: flex; align-items: center; gap: 4px; flex-wrap: wrap; font-variant-numeric: tabular-nums;
  & kbd { height: 15px; min-width: 15px; font-size: 9.5px; }
}
.acr-photo .acr-photo-group { padding: 12px 14px 14px; border-bottom: 1px solid var(--acr-photo-line); display: grid; gap: 9px; }
.acr-photo .acr-photo-group h3 button { margin-left: auto; font-size: 10.5px; letter-spacing: 0; text-transform: none; font-weight: 550; color: var(--acr-photo-faint); padding: 2px 6px; border-radius: 5px;
  &:hover:not(:disabled) { color: var(--acr-photo-accent); background: var(--acr-photo-hover); }
}
.acr-photo .acr-photo-sl { display: grid; grid-template-columns: minmax(0, 1fr) 44px; gap: 3px 8px; align-items: center;
  & label { font-size: 12px; color: var(--acr-photo-mute); cursor: default; user-select: none; }
  & output { text-align: right; font: 11px var(--acr-photo-mono); color: var(--acr-photo-faint); font-variant-numeric: tabular-nums; transition: color .2s; }
  & output.is-set { color: var(--acr-photo-accent); }
  & input { grid-column: 1 / -1; }
}
.acr-photo input[type="range"] {
  -webkit-appearance: none; appearance: none; width: 100%; height: 16px; margin: 0; background: transparent; cursor: ew-resize;
  --lo: 50%; --hi: 50%;
  --track: linear-gradient(to right, var(--acr-photo-line2) var(--lo), var(--acr-photo-accent) var(--lo) var(--hi), var(--acr-photo-line2) var(--hi));
  &::-webkit-slider-runnable-track { height: 3px; border-radius: 3px; background: var(--track); }
  &::-moz-range-track { height: 3px; border-radius: 3px; background: var(--track); }
  &::-webkit-slider-thumb { -webkit-appearance: none; width: 13px; height: 13px; margin-top: -5px; border-radius: 50%; background: var(--acr-photo-ink); box-shadow: 0 0 0 3px var(--acr-photo-panel), 0 1px 4px oklch(0 0 0 / .6); transition: transform .3s var(--acr-photo-spring); }
  &::-moz-range-thumb { width: 13px; height: 13px; border: 0; border-radius: 50%; background: var(--acr-photo-ink); box-shadow: 0 0 0 3px var(--acr-photo-panel); }
  &:active::-webkit-slider-thumb { transform: scale(1.25); }
  &:focus-visible { outline: none; &::-webkit-slider-thumb { box-shadow: 0 0 0 3px var(--acr-photo-panel), 0 0 0 5px var(--acr-photo-accent); } }
  &.is-temp { --track: linear-gradient(to right, oklch(0.62 0.12 250), oklch(0.5 0.01 80) 50%, oklch(0.78 0.15 75)); }
  &.is-tint { --track: linear-gradient(to right, oklch(0.66 0.15 145), oklch(0.5 0.01 80) 50%, oklch(0.64 0.17 340)); }
  &.is-sat { --track: linear-gradient(to right, oklch(0.5 0 0), oklch(0.6 0.08 30) 50%, oklch(0.68 0.2 30), oklch(0.75 0.17 90), oklch(0.68 0.14 160)); }
}

/* ── narrow nav ──────────────────────────────────────── */
.acr-photo .acr-photo-mnav { display: none; border-top: 1px solid var(--acr-photo-line); background: var(--acr-photo-panel); padding: 4px 6px calc(4px + env(safe-area-inset-bottom, 0px)); }
.acr-photo .acr-photo-mnav button {
  flex: 1; display: grid; justify-items: center; gap: 2px; padding: 6px 0 4px; border-radius: 8px; font-size: 10.5px; font-weight: 600; color: var(--acr-photo-faint);
  & svg { width: 18px; height: 18px; }
  &[aria-selected="true"] { color: var(--acr-photo-accent); background: var(--acr-photo-hover); }
}

/* ── toast & dialog ──────────────────────────────────── */
.acr-photo .acr-photo-toast {
  position: absolute; left: 50%; bottom: 18px; z-index: 50; max-width: calc(100% - 32px); padding: 8px 14px; border-radius: 10px; pointer-events: none;
  background: var(--acr-photo-ink); color: var(--acr-photo-bg); font-weight: 560; box-shadow: 0 10px 30px oklch(0 0 0 / .5);
  opacity: 0; transform: translate(-50%, 10px) scale(.96); transition: opacity .25s, transform .4s var(--acr-photo-out);
  &.is-on { opacity: 1; transform: translate(-50%, 0) scale(1); }
}
.acr-photo .acr-photo-scrim {
  position: absolute; inset: 0; z-index: 40; display: grid; place-items: center; padding: 16px; background: oklch(0.1 0.01 60 / .55); backdrop-filter: blur(3px);
  transition: opacity .25s; @starting-style { opacity: 0; }
}
.acr-photo .acr-photo-dlg {
  width: min(420px, 100%); max-height: 100%; overflow: auto; border-radius: 14px; background: var(--acr-photo-panel); box-shadow: 0 0 0 1px var(--acr-photo-line2), 0 30px 70px -10px oklch(0 0 0 / .7);
