  &:focus-visible { outline: 2.5px solid var(--acr-palette-fg); outline-offset: -7px; }
  @starting-style { flex-grow: 0; }
  &.is-drag { z-index: 5; box-shadow: 0 18px 40px -10px oklch(0.2 0.02 60 / .55); border-radius: 10px; transition: none; }
  &:has(.acr-palette-editor:not([hidden])) { flex-grow: 1.6; }
}
.acr-palette .acr-palette-swtools {
  position: absolute; top: 12px; left: 10px; right: 10px; display: flex; gap: 2px; align-items: center;
  & button, & .acr-palette-grip { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 8px; color: inherit; opacity: 0; transform: translateY(-3px);
    transition: opacity .2s, transform .3s var(--acr-palette-out), background-color .15s; transition-delay: calc(var(--k, 0) * 30ms); }
  & button:hover { background: color-mix(in oklch, var(--acr-palette-fg) 14%, transparent); }
  & [aria-pressed="true"], & [aria-expanded="true"] { opacity: 1; transform: none; background: color-mix(in oklch, var(--acr-palette-fg) 14%, transparent); }
  & [aria-pressed="true"] .acr-palette-unlock, & [aria-pressed="false"] .acr-palette-lockd { display: none; }
  & .acr-palette-grip { margin-left: auto; cursor: grab; touch-action: none; }
}
.acr-palette .acr-palette-sw:hover .acr-palette-swtools > *, .acr-palette .acr-palette-sw:focus-within .acr-palette-swtools > * { opacity: 1; transform: none; }
.acr-palette .acr-palette-swinfo { display: grid; gap: 2px; min-width: 0; }
.acr-palette .acr-palette-hex {
  justify-self: start; max-width: 100%; font: 700 clamp(15px, 2.3cqi, 23px)/1.1 var(--acr-palette-mono); letter-spacing: .02em; padding: 2px 6px; translate: -6px 0; border-radius: 7px;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis; transition: background-color .15s;
  &:hover { background: color-mix(in oklch, var(--acr-palette-fg) 12%, transparent); }
}
.acr-palette .acr-palette-swname { font-weight: 620; font-size: 13px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.acr-palette .acr-palette-lch { font: 10.5px var(--acr-palette-mono); opacity: .72; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-variant-numeric: tabular-nums; }
.acr-palette .acr-palette-badge { justify-self: start; margin-top: 6px; display: inline-flex; gap: 5px; align-items: center; padding: 2px 7px; border-radius: 99px; font: 600 10px var(--acr-palette-mono);
  background: color-mix(in oklch, var(--acr-palette-fg) 12%, transparent); font-variant-numeric: tabular-nums; white-space: nowrap;
}
.acr-palette .acr-palette-gamut { display: inline-flex; align-items: center; gap: 4px; font-size: 10.5px; font-weight: 600; & svg { width: 12px; height: 12px; } }
.acr-palette .acr-palette-swinfo.is-new > * { animation: acr-palette-roll .5s var(--acr-palette-out) both; animation-delay: calc(var(--i, 0) * 45ms + var(--k, 0) * 25ms); }
@keyframes acr-palette-roll { from { opacity: 0; transform: translateY(8px); filter: blur(2px); } }
.acr-palette .acr-palette-ins {
  position: absolute; top: 50%; right: -15px; z-index: 4; width: 30px; height: 30px; margin-top: -15px; border-radius: 50%; display: grid; place-items: center;
  background: var(--acr-palette-surface); color: var(--acr-palette-ink); box-shadow: 0 2px 8px oklch(0.2 0.02 60 / .25), 0 0 0 1px var(--acr-palette-line);
  opacity: 0; transform: scale(.6); transition: opacity .2s, transform .35s var(--acr-palette-spring);
  &:hover { transform: scale(1.1); }
  &:focus-visible { opacity: 1; transform: none; }
}
.acr-palette .acr-palette-sw:hover .acr-palette-ins { opacity: 1; transform: none; }

/* inline editor */
.acr-palette .acr-palette-editor {
  margin-top: 12px; padding: 10px; border-radius: 11px; display: grid; gap: 8px; color: var(--acr-palette-ink); min-width: 0; width: 100%;
  background: var(--acr-palette-surface); box-shadow: 0 10px 28px -10px oklch(0.2 0.02 60 / .45), 0 0 0 1px var(--acr-palette-line);
  transition: opacity .2s, transform .35s var(--acr-palette-out);
  @starting-style { opacity: 0; transform: translateY(8px); }
  & label { display: grid; grid-template-columns: 14px minmax(0, 1fr) 40px; align-items: center; gap: 6px; font: 600 10.5px var(--acr-palette-mono); color: var(--acr-palette-mute); }
  & output { text-align: right; font-variant-numeric: tabular-nums; color: var(--acr-palette-ink); }
  & input[type="range"] { -webkit-appearance: none; appearance: none; width: 100%; min-width: 0; height: 16px; margin: 0; background: transparent; cursor: ew-resize; }
  & input[type="range"]::-webkit-slider-runnable-track { height: 10px; border-radius: 5px; background: var(--tr); box-shadow: inset 0 0 0 1px oklch(0 0 0 / .08); }
  & input[type="range"]::-moz-range-track { height: 10px; border-radius: 5px; background: var(--tr); }
  & input[type="range"]::-webkit-slider-thumb { -webkit-appearance: none; width: 14px; height: 14px; margin-top: -2px; border-radius: 50%; background: transparent; box-shadow: 0 0 0 2.5px white, 0 0 0 3.5px oklch(0 0 0 / .35), 0 2px 5px oklch(0 0 0 / .3); }
  & input[type="range"]::-moz-range-thumb { width: 12px; height: 12px; border: 2.5px solid white; border-radius: 50%; background: transparent; }
  & .acr-palette-hexin { display: flex; gap: 6px; }
  & input[type="text"] { width: 0; min-width: 0; flex: 1; height: 28px; border: 0; border-radius: 7px; padding: 0 8px; font: 600 12px var(--acr-palette-mono); background: var(--acr-palette-bg); box-shadow: inset 0 0 0 1px var(--acr-palette-line2); text-transform: uppercase; }
  & input[type="text"]:focus-visible { outline: none; box-shadow: inset 0 0 0 1.5px var(--acr-palette-accent); }
  & input[aria-invalid="true"] { box-shadow: inset 0 0 0 1.5px oklch(0.6 0.2 25); }
  & .acr-palette-done { height: 28px; padding: 0 10px; border-radius: 7px; font-weight: 650; font-size: 12px; background: var(--acr-palette-ink); color: var(--acr-palette-surface); }
}

/* footer */
.acr-palette .acr-palette-foot { display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap; min-width: 0; }
.acr-palette .acr-palette-vision, .acr-palette .acr-palette-algo { display: inline-flex; align-items: center; gap: 2px; padding: 2px; border-radius: 10px; background: var(--acr-palette-hover);
  & .acr-palette-lbl { padding: 0 8px 0 6px; }
  & button { height: 26px; padding: 0 10px; border-radius: 8px; font-size: 12px; font-weight: 560; color: var(--acr-palette-mute); transition: background-color .2s, color .2s, box-shadow .2s; }
  & button:hover { color: var(--acr-palette-ink); }
  & button[aria-checked="true"] { background: var(--acr-palette-surface); color: var(--acr-palette-ink); box-shadow: 0 1px 2px oklch(0.2 0.02 60 / .15), inset 0 0 0 1px var(--acr-palette-line); }
}
.acr-palette .acr-palette-keys { display: flex; gap: 14px; font-size: 11.5px; color: var(--acr-palette-faint); flex-wrap: wrap;
  & span { display: inline-flex; gap: 4px; align-items: center; white-space: nowrap; }
}

/* ── side ────────────────────────────────────────────── */
.acr-palette .acr-palette-side { grid-area: side; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); border-left: 1px solid var(--acr-palette-line); background: var(--acr-palette-surface); }
.acr-palette .acr-palette-tabs { display: flex; gap: 4px; padding: 10px 12px 0; border-bottom: 1px solid var(--acr-palette-line);
  & button { position: relative; height: 34px; padding: 0 10px; font-weight: 600; font-size: 12.5px; color: var(--acr-palette-faint); transition: color .2s; }
  & button::after { content: ""; position: absolute; left: 8px; right: 8px; bottom: -1px; height: 2px; border-radius: 2px; background: var(--acr-palette-ink); transform: scaleX(0); transition: transform .35s var(--acr-palette-out); }
  & button:hover { color: var(--acr-palette-ink); }
  & button[aria-selected="true"] { color: var(--acr-palette-ink); &::after { transform: none; } }
  & span { font: 600 10px var(--acr-palette-mono); padding: 1px 5px; border-radius: 99px; background: var(--acr-palette-hover); margin-left: 3px; }
}
.acr-palette .acr-palette-panel { min-height: 0; overflow-y: auto; overscroll-behavior: contain; scrollbar-width: thin; padding: 14px; display: grid; align-content: start; grid-auto-rows: max-content; gap: 12px; }
.acr-palette .acr-palette-algo { justify-self: start; }

.acr-palette .acr-palette-pair { border-radius: 12px; overflow: hidden; box-shadow: 0 0 0 1px var(--acr-palette-line); background: var(--acr-palette-surface); }
.acr-palette .acr-palette-pairpv { padding: 14px 14px 12px; background: var(--pb); color: var(--pf); transition: background-color .4s var(--acr-palette-ease), color .4s var(--acr-palette-ease);
  & h4 { font-size: 17px; font-weight: 700; letter-spacing: -.01em; line-height: 1.15; text-wrap: balance; }
  & p { margin-top: 5px; font-size: 12px; line-height: 1.45; text-wrap: pretty; }
}
.acr-palette .acr-palette-pairmeta { display: grid; grid-template-columns: auto 1fr; gap: 8px 12px; align-items: center; padding: 10px 14px 12px; font-size: 12px; }
.acr-palette .acr-palette-big { font: 700 26px/1 var(--acr-palette-mono); font-variant-numeric: tabular-nums; letter-spacing: -.02em; }
.acr-palette .acr-palette-checks { display: flex; flex-wrap: wrap; gap: 4px; justify-content: flex-end; }
.acr-palette .acr-palette-ck { display: inline-flex; align-items: center; gap: 4px; padding: 2px 7px; border-radius: 99px; font-size: 10.5px; font-weight: 650; white-space: nowrap;
  background: oklch(0.94 0.05 150); color: oklch(0.38 0.1 150);
  & svg { width: 11px; height: 11px; stroke-width: 2.4; }
  &.is-fail { background: oklch(0.94 0.035 25); color: oklch(0.45 0.15 25); }
}
.acr-palette .acr-palette-pairmeta small { grid-column: 1 / -1; color: var(--acr-palette-faint); font-size: 11px; text-wrap: pretty; }

.acr-palette .acr-palette-grid { display: grid; grid-template-columns: 22px repeat(var(--n), minmax(0, 1fr)); gap: 3px; }
.acr-palette .acr-palette-grid [role="row"] { display: contents; }
.acr-palette .acr-palette-gh { display: grid; place-items: center; height: 22px; & i { width: 14px; height: 14px; border-radius: 50%; background: var(--c); box-shadow: inset 0 0 0 1px oklch(0 0 0 / .12); } }
.acr-palette .acr-palette-cell {
  position: relative; aspect-ratio: 1; min-height: 34px; border-radius: 7px; display: grid; place-content: center; justify-items: center; gap: 1px; background: var(--b); color: var(--f);
  transition: transform .3s var(--acr-palette-spring), box-shadow .2s, background-color .4s var(--acr-palette-ease), color .4s var(--acr-palette-ease);
  & b { font-size: clamp(11px, 1.35cqi, 15px); font-weight: 700; line-height: 1; }
  & small { font: 600 9px/1 var(--acr-palette-mono); font-variant-numeric: tabular-nums; white-space: nowrap; }
  &.is-fail b, &.is-fail small { opacity: .38; }
  &.is-diag { pointer-events: none; & b { opacity: .3; } }
  &:hover { transform: scale(1.08); z-index: 2; box-shadow: 0 6px 16px -6px oklch(0.2 0.02 60 / .5); }
  &[aria-selected="true"] { box-shadow: 0 0 0 2px var(--acr-palette-surface), 0 0 0 3.5px var(--acr-palette-ink); z-index: 1; }
}
.acr-palette .acr-palette-grid.is-fresh .acr-palette-cell { animation: acr-palette-pop .45s var(--acr-palette-out) both; animation-delay: calc(var(--d, 0) * 14ms); }
@keyframes acr-palette-pop { from { opacity: 0; transform: scale(.85); } }
.acr-palette .acr-palette-sum { font-size: 12px; color: var(--acr-palette-mute); text-wrap: pretty; & b { color: var(--acr-palette-ink); font-variant-numeric: tabular-nums; } }

/* preview mock */
.acr-palette .acr-palette-pvbar { display: flex; justify-content: space-between; align-items: center; }
.acr-palette .acr-palette-chip { height: 26px; padding: 0 10px; border-radius: 99px; font-size: 12px; font-weight: 600; box-shadow: inset 0 0 0 1px var(--acr-palette-line2); transition: background-color .2s, color .2s;
  &:hover { background: var(--acr-palette-hover); }
  &[aria-pressed="true"] { background: var(--acr-palette-ink); color: var(--acr-palette-surface); box-shadow: none; }
}
.acr-palette .acr-palette-mock { border-radius: 12px; overflow: hidden; background: var(--m-bg); color: var(--m-ink); box-shadow: 0 0 0 1px var(--acr-palette-line), 0 10px 26px -14px oklch(0.2 0.02 60 / .4); transition: background-color .45s, color .45s;
  & * { transition: background-color .45s var(--acr-palette-ease), color .45s var(--acr-palette-ease), border-color .45s; }
  & nav { display: flex; align-items: center; justify-content: space-between; padding: 10px 12px; font-size: 11px; border-bottom: 1px solid color-mix(in oklch, var(--m-ink) 12%, transparent); }
  & nav b { font-size: 12.5px; letter-spacing: -.01em; display: flex; gap: 6px; align-items: center; }
  & nav b i { width: 12px; height: 12px; border-radius: 4px; background: var(--m-acc); }
  & nav span { color: var(--m-mute); }
