  & small { font: 650 9.5px var(--acr-palette-mono); letter-spacing: .1em; color: var(--m-acc); }
  & h4 { margin-top: 4px; font-size: 19px; line-height: 1.1; letter-spacing: -.02em; text-wrap: balance; }
  & p { margin-top: 6px; font-size: 11.5px; color: var(--m-mute); text-wrap: pretty; }
  & .acr-palette-mbtns { display: flex; gap: 6px; margin-top: 12px; }
  & .acr-palette-mbtns span { padding: 6px 10px; border-radius: 7px; font-size: 11px; font-weight: 650; }
  & .acr-palette-mbtns span:first-child { background: var(--m-acc); color: var(--m-accink); }
  & .acr-palette-mbtns span:last-child { box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--m-ink) 25%, transparent); }
  & .acr-palette-mstats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; padding: 0 12px 12px; }
  & .acr-palette-mstats div { padding: 8px; border-radius: 8px; background: var(--m-surf); }
  & .acr-palette-mstats b { display: block; font-size: 15px; font-variant-numeric: tabular-nums; }
  & .acr-palette-mstats span { font-size: 10px; color: var(--m-mute); }
  & .acr-palette-mstats div:nth-child(2) { background: var(--m-acc2); color: var(--m-hiink); }
  & .acr-palette-mstats div:nth-child(2) span { color: inherit; opacity: .78; }
}
.acr-palette .acr-palette-roles { display: grid; gap: 4px; }
.acr-palette .acr-palette-roles li { display: grid; grid-template-columns: 18px 1fr auto auto; align-items: center; gap: 8px; padding: 5px 4px 5px 6px; border-radius: 8px; font-size: 12px;
  & i { width: 18px; height: 18px; border-radius: 5px; background: var(--c); box-shadow: inset 0 0 0 1px oklch(0 0 0 / .12); }
  & span { color: var(--acr-palette-faint); font: 11px var(--acr-palette-mono); }
  & button { height: 24px; padding: 0 8px; border-radius: 6px; font-size: 11px; font-weight: 600; color: var(--acr-palette-mute); box-shadow: inset 0 0 0 1px var(--acr-palette-line); }
  & button:hover { background: var(--acr-palette-hover); color: var(--acr-palette-ink); }
  &:hover { background: var(--acr-palette-hover); }
}

/* library */
.acr-palette .acr-palette-lib { display: grid; gap: 8px; }
.acr-palette .acr-palette-lib li { display: grid; grid-template-columns: 1fr auto; gap: 4px; align-items: center; animation: acr-palette-pop .4s var(--acr-palette-out) both; animation-delay: calc(var(--i, 0) * 35ms); }
.acr-palette .acr-palette-libload { display: grid; gap: 6px; padding: 8px; border-radius: 10px; text-align: left; transition: background-color .2s;
  &:hover { background: var(--acr-palette-hover); }
  &[aria-current="true"] { background: var(--acr-palette-acc-soft); }
  & .acr-palette-strip { display: flex; height: 30px; border-radius: 7px; overflow: hidden; box-shadow: inset 0 0 0 1px oklch(0 0 0 / .06); }
  & .acr-palette-strip i { flex: 1; background: var(--c); transition: flex-grow .3s var(--acr-palette-out); }
  &:hover .acr-palette-strip i:hover { flex-grow: 1.8; }
  & span { display: flex; justify-content: space-between; font-size: 12px; font-weight: 600; }
  & small { font: 10.5px var(--acr-palette-mono); color: var(--acr-palette-faint); font-weight: 400; }
}
.acr-palette .acr-palette-libdel { display: grid; place-items: center; width: 28px; height: 28px; border-radius: 8px; color: var(--acr-palette-faint); &:hover { background: var(--acr-palette-hover); color: oklch(0.55 0.18 25); } }
.acr-palette .acr-palette-empty { padding: 24px 8px; text-align: center; color: var(--acr-palette-faint); font-size: 12px; text-wrap: balance; }

/* ── narrow nav, toast, dialog ───────────────────────── */
.acr-palette .acr-palette-mnav { display: none; gap: 2px; padding: 5px 6px; border-top: 1px solid var(--acr-palette-line); background: var(--acr-palette-surface);
  & button { flex: 1; height: 34px; border-radius: 8px; font-size: 12px; font-weight: 600; color: var(--acr-palette-faint); }
  & button[aria-selected="true"] { color: var(--acr-palette-ink); background: var(--acr-palette-hover); }
}
.acr-palette .acr-palette-toast {
  position: absolute; left: 50%; bottom: 22px; z-index: 60; max-width: calc(100% - 32px); padding: 8px 14px; border-radius: 10px; pointer-events: none; display: flex; gap: 8px; align-items: center;
  background: var(--acr-palette-ink); color: var(--acr-palette-surface); font-weight: 560; box-shadow: 0 12px 30px -8px oklch(0.2 0.02 60 / .5);
  opacity: 0; transform: translate(-50%, 10px) scale(.96); transition: opacity .25s, transform .4s var(--acr-palette-out);
  &.is-on { opacity: 1; transform: translate(-50%, 0); }
  & i { width: 12px; height: 12px; border-radius: 4px; background: var(--c, transparent); box-shadow: 0 0 0 1px oklch(1 0 0 / .3); }
}
.acr-palette .acr-palette-scrim { position: absolute; inset: 0; z-index: 50; display: grid; place-items: center; padding: 16px; background: oklch(0.25 0.02 60 / .28); backdrop-filter: blur(2px);
  transition: opacity .25s; @starting-style { opacity: 0; } }
.acr-palette .acr-palette-dlg {
  width: min(560px, 100%); max-height: 100%; display: grid; grid-template-rows: auto minmax(0, 1fr) auto; border-radius: 16px; background: var(--acr-palette-surface); overflow: hidden;
  box-shadow: 0 0 0 1px var(--acr-palette-line), 0 30px 70px -16px oklch(0.2 0.02 60 / .5);
  transition: transform .45s var(--acr-palette-spring), opacity .25s; @starting-style { transform: translateY(14px) scale(.97); opacity: 0; }
  & header, & footer { display: flex; align-items: center; gap: 10px; padding: 12px 12px 12px 18px; }
  & header { border-bottom: 1px solid var(--acr-palette-line); flex-wrap: wrap; }
  & h2 { font-size: 15px; font-weight: 700; margin-right: auto; text-wrap: balance; & span { color: var(--acr-palette-faint); font-weight: 500; } }
  & footer { justify-content: space-between; border-top: 1px solid var(--acr-palette-line); font: 11px var(--acr-palette-mono); color: var(--acr-palette-faint); }
}
.acr-palette .acr-palette-code { margin: 0; padding: 14px 18px; overflow: auto; font: 12px/1.6 var(--acr-palette-mono); background: var(--acr-palette-bg); white-space: pre; tab-size: 2; min-height: 160px;
  & .k { color: oklch(0.5 0.14 300); } & .s { color: oklch(0.5 0.12 150); } & .n { color: oklch(0.55 0.15 40); } & .c { color: var(--acr-palette-faint); font-style: italic; }
  & i { display: inline-block; width: .8em; height: .8em; margin-right: .4em; border-radius: 3px; vertical-align: -1px; background: var(--c); box-shadow: inset 0 0 0 1px oklch(0 0 0 / .15); }
}

/* ── container queries ───────────────────────────────── */
@container acr-palette (max-width: 1060px) {
  .acr-palette .acr-palette-keys { display: none; }
  .acr-palette .acr-palette-btn[data-act="export"] span { display: none; }
}
@container acr-palette (max-width: 959px) {
  .acr-palette .acr-palette-body { grid-template-columns: minmax(0, 1fr) 300px; }
  .acr-palette .acr-palette-name { display: none; }
  .acr-palette .acr-palette-vision .acr-palette-lbl { display: none; }
}
@container acr-palette (max-width: 759px) {
  .acr-palette .acr-palette-body { grid-template-columns: minmax(0, 1fr); grid-template-areas: "main"; }
  .acr-palette .acr-palette-side { grid-area: main; border: 0; grid-template-rows: minmax(0, 1fr); }
  .acr-palette .acr-palette-tabs { display: none; }
  .acr-palette[data-view="palette"] .acr-palette-side { display: none; }
  .acr-palette:not([data-view="palette"]) .acr-palette-main { display: none; }
  .acr-palette .acr-palette-mnav { display: flex; }
  .acr-palette .acr-palette-main { padding: 10px; }
  .acr-palette .acr-palette-swatches { flex-direction: column; }
