@property --acr-gradient-ang { syntax: "<angle>"; inherits: true; initial-value: 135deg; }
@property --acr-gradient-px { syntax: "<percentage>"; inherits: true; initial-value: 50%; }
@property --acr-gradient-py { syntax: "<percentage>"; inherits: true; initial-value: 50%; }
.acr-gradient {
  /* re-theme with these four */
  --acr-gradient-bg: oklch(0.972 0.005 85);
  --acr-gradient-surface: oklch(0.995 0.002 85);
  --acr-gradient-ink: oklch(0.25 0.015 75);
  --acr-gradient-accent: oklch(0.56 0.15 158);
  /* derived */
  --acr-gradient-line: color-mix(in oklch, var(--acr-gradient-ink) 10%, transparent);
  --acr-gradient-line2: color-mix(in oklch, var(--acr-gradient-ink) 18%, transparent);
  --acr-gradient-hover: color-mix(in oklch, var(--acr-gradient-ink) 5%, transparent);
  --acr-gradient-mute: color-mix(in oklch, var(--acr-gradient-ink) 64%, var(--acr-gradient-bg));
  --acr-gradient-faint: color-mix(in oklch, var(--acr-gradient-ink) 42%, var(--acr-gradient-bg));
  --acr-gradient-acc-soft: color-mix(in oklch, var(--acr-gradient-accent) 13%, var(--acr-gradient-surface));
  --acr-gradient-check: repeating-conic-gradient(oklch(0.93 0.004 85) 0 25%, oklch(0.99 0.002 85) 0 50%) 0 0 / 14px 14px;
  --acr-gradient-ease: cubic-bezier(.2, .8, .2, 1);
  --acr-gradient-out: cubic-bezier(.16, 1, .3, 1);
  --acr-gradient-spring: linear(0, 0.12 6%, 0.46 14%, 0.86 24%, 1.04 32%, 1.07 38%, 1.03 48%, 0.996 62%, 1);
  --acr-gradient-mono: ui-monospace, Menlo, monospace;

  position: relative; width: 100%; height: var(--acr-gradient-h, 680px); box-sizing: border-box;
  container-type: inline-size; container-name: acr-gradient; overflow: clip; isolation: isolate;
  display: grid; grid-template-rows: auto minmax(0, 1fr) auto;
  border-radius: 16px; background: var(--acr-gradient-bg); color: var(--acr-gradient-ink); color-scheme: light;
  accent-color: var(--acr-gradient-accent); box-shadow: inset 0 0 0 1px var(--acr-gradient-line);
  font: 12.5px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; -webkit-tap-highlight-color: transparent;
  transition: --acr-gradient-ang .7s var(--acr-gradient-spring), --acr-gradient-px .5s var(--acr-gradient-out), --acr-gradient-py .5s var(--acr-gradient-out);
  &.is-live { transition: none; }

  & *, & *::before, & *::after { box-sizing: border-box; }
