  & h3, & p, & ol { margin: 0; padding: 0; }
  & ol { list-style: none; }
  & [hidden] { display: none !important; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { display: inline-grid; place-items: center; min-width: 16px; height: 16px; padding: 0 4px; border-radius: 4px; font: 600 9.5px/1 var(--acr-gradient-mono); color: var(--acr-gradient-mute); background: var(--acr-gradient-surface); box-shadow: inset 0 0 0 1px var(--acr-gradient-line2); }
  & h3 { display: flex; align-items: center; gap: 8px; min-height: 24px; font-size: 10.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--acr-gradient-faint); }
  & h3 > span:not(.acr-gradient-hacts) { margin-left: auto; letter-spacing: 0; text-transform: none; font-weight: 500; font-size: 11px; font-variant-numeric: tabular-nums; }
}

/* ── top ─────────────────────────────────────────────── */
.acr-gradient .acr-gradient-top { display: flex; align-items: center; gap: 12px; padding: 10px 12px 10px 18px; border-bottom: 1px solid var(--acr-gradient-line); }
.acr-gradient .acr-gradient-brand { display: flex; align-items: baseline; gap: 8px; font-weight: 760; font-size: 14px; letter-spacing: -.015em;
  & svg { width: 20px; height: 20px; color: var(--acr-gradient-accent); align-self: center; }
  & em { font-style: normal; font-weight: 500; font-size: 12px; color: var(--acr-gradient-faint); letter-spacing: 0; }
}
.acr-gradient .acr-gradient-acts { margin-left: auto; display: flex; align-items: center; gap: 6px; }
.acr-gradient .acr-gradient-ib, .acr-gradient .acr-gradient-mini {
  display: grid; place-items: center; width: 32px; height: 32px; border-radius: 9px; color: var(--acr-gradient-mute); transition: background-color .18s, color .18s, transform .35s var(--acr-gradient-spring);
  &:hover:not(:disabled) { background: var(--acr-gradient-hover); color: var(--acr-gradient-ink); }
  &:active:not(:disabled) { transform: scale(.9); }
}
.acr-gradient .acr-gradient-mini { width: 26px; height: 26px; border-radius: 7px; & svg { width: 14px; height: 14px; } }
.acr-gradient .acr-gradient-btn {
  display: inline-flex; align-items: center; gap: 7px; height: 32px; padding: 0 11px; border-radius: 9px; font-weight: 580; white-space: nowrap;
  background: var(--acr-gradient-surface); box-shadow: inset 0 0 0 1px var(--acr-gradient-line2); transition: background-color .18s;
  &:hover { background: var(--acr-gradient-hover); }
