}
.acr-gradient .acr-gradient-primary {
  display: inline-flex; align-items: center; gap: 7px; height: 32px; padding: 0 13px; border-radius: 9px; font-weight: 650; white-space: nowrap;
  background: var(--acr-gradient-ink); color: var(--acr-gradient-surface); box-shadow: 0 1px 2px oklch(0 0 0 / .2), inset 0 1px 0 oklch(1 0 0 / .14);
  transition: transform .35s var(--acr-gradient-spring), background-color .2s;
  &:hover { background: color-mix(in oklch, var(--acr-gradient-ink) 85%, var(--acr-gradient-accent)); }
  &:active { transform: scale(.96); }
}

/* ── body grid ───────────────────────────────────────── */
.acr-gradient .acr-gradient-body { min-height: 0; display: grid; grid-template-columns: 222px minmax(0, 1fr) 286px; grid-template-areas: "left center right"; }
.acr-gradient .acr-gradient-left, .acr-gradient .acr-gradient-right { min-height: 0; overflow-y: auto; overscroll-behavior: contain; scrollbar-width: thin; background: var(--acr-gradient-surface); }
.acr-gradient .acr-gradient-left { grid-area: left; border-right: 1px solid var(--acr-gradient-line); }
.acr-gradient .acr-gradient-right { grid-area: right; border-left: 1px solid var(--acr-gradient-line); }
.acr-gradient .acr-gradient-sec { padding: 12px 14px 14px; border-bottom: 1px solid var(--acr-gradient-line); display: grid; gap: 10px; }
.acr-gradient .acr-gradient-hacts { margin-left: auto; display: flex; gap: 2px; }

/* layers */
.acr-gradient .acr-gradient-layers { display: grid; gap: 3px; }
.acr-gradient .acr-gradient-layer {
  display: grid; grid-template-columns: 34px minmax(0, 1fr) auto; grid-template-areas: "thumb name name" "thumb meta acts"; align-items: center; column-gap: 9px; padding: 6px 4px 5px 6px; border-radius: 10px; transition: background-color .15s;
  animation: acr-gradient-in .35s var(--acr-gradient-out) both;
  &:hover { background: var(--acr-gradient-hover); }
  &:has([aria-selected="true"]) { background: var(--acr-gradient-acc-soft); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--acr-gradient-accent) 35%, transparent); }
  &.is-off .acr-gradient-lthumb, &.is-off .acr-gradient-lname { opacity: .4; }
}
@keyframes acr-gradient-in { from { opacity: 0; transform: translateY(-4px); } }
.acr-gradient .acr-gradient-lthumb { grid-area: thumb; width: 34px; height: 34px; border-radius: 7px; background: var(--g), var(--acr-gradient-check); box-shadow: inset 0 0 0 1px oklch(0 0 0 / .08); }
.acr-gradient .acr-gradient-lname { grid-area: 1 / 2 / 3 / 3; align-self: stretch; display: grid; align-content: start; text-align: left; min-width: 0; padding: 1px 0;
  & b { width: calc(100% + 80px); font-weight: 600; font-size: 12px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & small { max-width: 100%; font: 10.5px var(--acr-gradient-mono); color: var(--acr-gradient-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  &:focus-visible { outline-offset: 0; border-radius: 4px; }
}
.acr-gradient .acr-gradient-lacts { grid-area: 2 / 3 / 3 / 4; display: flex; gap: 0; position: relative; z-index: 1;
  & button { width: 24px; height: 24px; border-radius: 6px; display: grid; place-items: center; color: var(--acr-gradient-faint); }
  & button:hover:not(:disabled) { color: var(--acr-gradient-ink); background: var(--acr-gradient-hover); }
  & svg { width: 14px; height: 14px; }
  & [aria-pressed="false"] .acr-gradient-eyeoff, & [aria-pressed="true"] .acr-gradient-eyeon { display: none; }
}

/* presets */
.acr-gradient .acr-gradient-presets { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.acr-gradient .acr-gradient-preset {
  display: grid; gap: 5px; align-content: start; text-align: left; font-size: 11.5px; color: var(--acr-gradient-mute);
  animation: acr-gradient-in .4s var(--acr-gradient-out) both; animation-delay: calc(var(--i, 0) * 35ms);
  & i { display: block; aspect-ratio: 4 / 3; border-radius: 9px; background: var(--g); background-blend-mode: var(--gb, normal); box-shadow: inset 0 0 0 1px oklch(0 0 0 / .06); transition: transform .35s var(--acr-gradient-spring), box-shadow .2s; }
  &:hover { color: var(--acr-gradient-ink); & i { transform: translateY(-2px) scale(1.03); box-shadow: 0 8px 18px -8px oklch(0.2 0.02 60 / .45); } }
}

/* ── centre ──────────────────────────────────────────── */
.acr-gradient .acr-gradient-center { grid-area: center; min-width: 0; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr) auto auto auto; gap: 10px; padding: 12px 16px 14px; }
.acr-gradient .acr-gradient-bar { display: flex; align-items: center; justify-content: space-between; gap: 10px; min-width: 0; }
.acr-gradient .acr-gradient-meta { font: 11px var(--acr-gradient-mono); color: var(--acr-gradient-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-variant-numeric: tabular-nums; }
.acr-gradient .acr-gradient-seg { display: inline-flex; padding: 2px; gap: 2px; border-radius: 10px; background: var(--acr-gradient-hover); box-shadow: inset 0 0 0 1px var(--acr-gradient-line);
  & button { height: 26px; padding: 0 10px; border-radius: 8px; font-size: 12px; font-weight: 560; color: var(--acr-gradient-mute); transition: background-color .2s, color .2s, box-shadow .2s; white-space: nowrap; }
  & button:hover { color: var(--acr-gradient-ink); }
  & button[aria-checked="true"] { background: var(--acr-gradient-surface); color: var(--acr-gradient-ink); box-shadow: 0 1px 2px oklch(0.2 0.02 60 / .15), inset 0 0 0 1px var(--acr-gradient-line); }
  &.acr-gradient-wide { display: flex; & button { flex: 1; } }
  &.acr-gradient-small button { height: 24px; padding: 0 8px; font-size: 11.5px; }
}
.acr-gradient .acr-gradient-stage { min-height: 0; border-radius: 14px; background: var(--acr-gradient-check); box-shadow: inset 0 0 0 1px var(--acr-gradient-line); overflow: hidden; display: grid; }
.acr-gradient .acr-gradient-pv {
  position: relative; display: grid; place-items: center; min-height: 0; cursor: crosshair; touch-action: none;
  & > * { display: none; }
}
.acr-gradient[data-mode="canvas"] .acr-gradient-pv { background: var(--g); background-blend-mode: var(--gb, normal); }
.acr-gradient[data-mode="canvas"] .acr-gradient-centre { display: block; }
.acr-gradient .acr-gradient-centre { position: absolute; left: var(--acr-gradient-px); top: var(--acr-gradient-py); width: 18px; height: 18px; margin: -9px 0 0 -9px; border-radius: 50%; pointer-events: none;
  box-shadow: 0 0 0 2px white, 0 0 0 3.5px oklch(0 0 0 / .3), inset 0 0 0 4px oklch(0 0 0 / .15); opacity: 0; transition: opacity .25s; }
.acr-gradient[data-type="radial"] .acr-gradient-centre, .acr-gradient[data-type="conic"] .acr-gradient-centre { opacity: .9; }
.acr-gradient[data-mode="card"] .acr-gradient-pv { background: oklch(0.9 0.01 85 / .55); cursor: default; }
.acr-gradient[data-mode="card"] .acr-gradient-card { display: grid; }
