/* ── Ramp · layered CSS gradient builder ───────────────────────────────
   The document is a stack of gradient layers (top first). The preview is
   plain CSS: the composed background string lives in --g on the root, and
   the selected layer reads its angle and centre from registered
   properties (--acr-gradient-ang / -px / -py), so preset angles and
   centres ease with a spring while drags update instantly. Stops are
   interpolated in the layer's colour space — sRGB, linear sRGB, OKLab or
   OKLCH — and the side-by-side strips show why that choice matters. */
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const clamp = (v, a, b) => v < a ? a : v > b ? b : v;
const esc = s => String(s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const r1 = v => Math.round(v * 10) / 10;

/* ── colour helpers ────────────────────────────────── */
const hexRgb = h => [1, 3, 5].map(i => parseInt(h.slice(i, i + 2), 16) / 255);
const rgbHex = c => '#' + c.map(v => Math.round(clamp(v, 0, 1) * 255).toString(16).padStart(2, '0')).join('').toUpperCase();
const toLin = v => v <= .04045 ? v / 12.92 : Math.pow((v + .055) / 1.055, 2.4);
const toGam = v => v <= .0031308 ? v * 12.92 : 1.055 * Math.pow(Math.max(0, v), 1 / 2.4) - .055;
function lab(c) {
  const [r, g, b] = c.map(toLin);
  const l = Math.cbrt(.4122214708 * r + .5363325363 * g + .0514459929 * b), m = Math.cbrt(.2119034982 * r + .6806995451 * g + .1073969566 * b), s = Math.cbrt(.0883024619 * r + .2817188376 * g + .6299787005 * b);
  return [.2104542553 * l + .793617785 * m - .0040720468 * s, 1.9779984951 * l - 2.428592205 * m + .4505937099 * s, .0259040371 * l + .7827717662 * m - .808675766 * s];
}
function unlab([L, a, b]) {
  const l = (L + .3963377774 * a + .2158037573 * b) ** 3, m = (L - .1055613458 * a - .0638541728 * b) ** 3, s = (L - .0894841775 * a - 1.291485548 * b) ** 3;
  return [4.0767416621 * l - 3.3077115913 * m + .2309699292 * s, -1.2684380046 * l + 2.6097574011 * m - .3413193965 * s, -.0041960863 * l - .7034186147 * m + 1.707614701 * s].map(v => toGam(clamp(v, 0, 1)));
}
function mix(h1, h2, t, space, longer) {
  const a = hexRgb(h1), b = hexRgb(h2);
  if (space === 'srgb') return rgbHex(a.map((v, i) => v + (b[i] - v) * t));
  if (space === 'srgb-linear') return rgbHex(a.map((v, i) => toGam(toLin(v) + (toLin(b[i]) - toLin(v)) * t)));
  const A = lab(a), B = lab(b);
  if (space === 'oklab') return rgbHex(unlab(A.map((v, i) => v + (B[i] - v) * t)));
  const ca = Math.hypot(A[1], A[2]), cb = Math.hypot(B[1], B[2]);
  let ha = Math.atan2(A[2], A[1]), hb = Math.atan2(B[2], B[1]);
  if (ca < .002) ha = hb; if (cb < .002) hb = ha;
  let dh = hb - ha;
  if (!longer) { if (dh > Math.PI) dh -= 2 * Math.PI; else if (dh < -Math.PI) dh += 2 * Math.PI; }
  else if (Math.abs(dh) < Math.PI && dh !== 0) dh += dh > 0 ? -2 * Math.PI : 2 * Math.PI;
  const h = ha + dh * t, c = ca + (cb - ca) * t, L = A[0] + (B[0] - A[0]) * t;
  return rgbHex(unlab([L, c * Math.cos(h), c * Math.sin(h)]));
}

/* ── model ─────────────────────────────────────────── */
let nid = 0;
const uid = p => p + (++nid);
const ST = (hex, a, at) => ({ id: uid('s'), hex, a, at });
const LY = o => Object.assign({ id: uid('l'), type: 'linear', angle: 135, x: 50, y: 50, shape: 'ellipse', space: 'oklch', longer: false, repeat: false, blend: 'normal', on: true, stops: [] }, o, { stops: o.stops.map(s => ST(...s)) });
const PRESETS = [
  ['Clay Sunrise', () => [LY({ type: 'radial', shape: 'circle', x: 24, y: 18, stops: [['#FFF1D6', .9, 0], ['#FFF1D6', 0, 46]] }), LY({ angle: 160, stops: [['#FBE3C4', 1, 0], ['#F2A57A', 1, 36], ['#D9645A', 1, 68], ['#6E3B4E', 1, 100]] })]],
  ['Matcha Foam', () => [LY({ angle: 180, space: 'oklab', stops: [['#F4F1E1', 1, 0], ['#CFE0A8', 1, 46], ['#7FA35B', 1, 100]] })]],
  ['Ember Line', () => [LY({ angle: 100, space: 'oklab', stops: [['#1F1A17', 1, 0], ['#1F1A17', 1, 38], ['#E2552D', 1, 52], ['#F7C04A', 1, 60], ['#1F1A17', 1, 74]] })]],
  ['Harbour Mist', () => [LY({ angle: 180, space: 'oklab', stops: [['#DCE7E4', 1, 0], ['#9DB9B6', 1, 55], ['#45666A', 1, 100]] })]],
  ['Peach Nectar', () => [LY({ type: 'radial', x: 70, y: 28, stops: [['#FFE2C2', 1, 0], ['#F7A08B', 1, 52], ['#C9677B', 1, 100]] })]],
  ['Hue Wheel', () => [LY({ type: 'conic', angle: 0, longer: true, stops: [['#E8705F', 1, 0], ['#E8705F', 1, 100]] })]],
  ['Night Ferry', () => [LY({ type: 'radial', shape: 'circle', x: 78, y: 82, blend: 'screen', stops: [['#F2B45C', .85, 0], ['#F2B45C', 0, 38]] }), LY({ angle: 200, stops: [['#0F2A2E', 1, 0], ['#1D4A49', 1, 52], ['#3E6B5C', 1, 100]] })]],
  ['Paper Lantern', () => [LY({ type: 'radial', shape: 'circle', x: 50, y: 58, space: 'oklab', stops: [['#FFE7B0', .95, 0], ['#FFB45E', .7, 30], ['#FFB45E', 0, 62]] }), LY({ angle: 180, stops: [['#2B1E1A', 1, 0], ['#4A2A22', 1, 100]] })]],
];
const SPACES = [['srgb', 'sRGB'], ['srgb-linear', 'Linear'], ['oklab', 'OKLab'], ['oklch', 'OKLCH']];
