  if (e.key === '[' || e.key === ']') { e.preventDefault(); const st = sorted(L()), i = st.findIndex(s => s.id === S.stop), n = st[clamp(i + (e.key === ']' ? 1 : -1), 0, st.length - 1)]; S.stop = n.id; render(); const el = $('[data-sid="' + n.id + '"]'); el && el.focus({ preventScroll: true }); }
  else if ((e.key === 'Delete' || e.key === 'Backspace') && !t.closest('button')) { e.preventDefault(); if (removeStop(S.stop)) { render(); commit(); toast('Stop removed'); } }
  else if (e.key === 'r' || e.key === 'R') $('[data-act="reverse"]').click();
  else if (e.key === 'c' || e.key === 'C') $('[data-act="copy"]').click();
  else if (e.key === 'd' || e.key === 'D') $('[data-act="dup"]').click();
