css:
.acr-beats {
  /* re-theme with these four (track colours below) */
  --acr-beats-bg: oklch(0.195 0.008 60);
  --acr-beats-panel: oklch(0.235 0.009 60);
  --acr-beats-ink: oklch(0.94 0.012 85);
  --acr-beats-accent: oklch(0.76 0.165 52);
  --acr-beats-t0: oklch(0.74 0.17 42);
  --acr-beats-t1: oklch(0.84 0.15 88);
  --acr-beats-t2: oklch(0.76 0.15 18);
  --acr-beats-t3: oklch(0.85 0.15 125);
  --acr-beats-t4: oklch(0.81 0.12 160);
  --acr-beats-t5: oklch(0.76 0.1 215);
  --acr-beats-t6: oklch(0.77 0.13 345);
  --acr-beats-t7: oklch(0.88 0.06 80);
  /* derived */
  --acr-beats-line: color-mix(in oklch, var(--acr-beats-ink) 9%, transparent);
  --acr-beats-line2: color-mix(in oklch, var(--acr-beats-ink) 16%, transparent);
  --acr-beats-hover: color-mix(in oklch, var(--acr-beats-ink) 6%, transparent);
  --acr-beats-mute: color-mix(in oklch, var(--acr-beats-ink) 62%, var(--acr-beats-bg));
  --acr-beats-faint: color-mix(in oklch, var(--acr-beats-ink) 38%, var(--acr-beats-bg));
  --acr-beats-well: color-mix(in oklch, var(--acr-beats-bg) 82%, black);
  --acr-beats-ease: cubic-bezier(.2, .8, .2, 1);
  --acr-beats-out: cubic-bezier(.16, 1, .3, 1);
  --acr-beats-spring: linear(0, 0.12 6%, 0.46 14%, 0.86 24%, 1.04 32%, 1.07 38%, 1.03 48%, 0.996 62%, 1);
  --acr-beats-mono: ui-monospace, Menlo, monospace;

  position: relative; width: 100%; height: var(--acr-beats-h, 680px); box-sizing: border-box;
  container-type: inline-size; container-name: acr-beats; overflow: clip; isolation: isolate;
  display: grid; grid-template-rows: auto minmax(0, 1fr) auto;
  border-radius: 16px; color: var(--acr-beats-ink); color-scheme: dark; accent-color: var(--acr-beats-accent);
  background: radial-gradient(120% 70% at 50% 0%, color-mix(in oklch, var(--acr-beats-bg) 88%, var(--acr-beats-ink)), var(--acr-beats-bg) 60%);
  box-shadow: inset 0 1px 0 oklch(1 0 0 / .05);
  font: 12.5px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; -webkit-font-smoothing: antialiased; -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--acr-beats-accent); outline-offset: 2px; }
  & button, & input { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & button:disabled { cursor: not-allowed; opacity: .35; }
  & h3, & p { margin: 0; }
  & [hidden] { display: none !important; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { display: inline-grid; place-items: center; min-width: 17px; height: 17px; padding: 0 4px; border-radius: 4px; font: 600 10px/1 var(--acr-beats-mono); color: var(--acr-beats-mute); background: var(--acr-beats-hover); box-shadow: inset 0 0 0 1px var(--acr-beats-line2); }
  & h3 { display: flex; align-items: baseline; gap: 8px; font-size: 13px; font-weight: 700; letter-spacing: -.01em;
    & small { margin-left: auto; font: 500 10.5px var(--acr-beats-mono); color: var(--acr-beats-faint); letter-spacing: 0; text-align: right; }
  }
  & input[type="range"] { -webkit-appearance: none; appearance: none; width: 100%; height: 16px; margin: 0; background: transparent; cursor: ew-resize; }
  & input[type="range"]::-webkit-slider-runnable-track { height: 3px; border-radius: 3px; background: linear-gradient(to right, var(--acr-beats-accent) var(--p, 50%), var(--acr-beats-line2) var(--p, 50%)); }
  & input[type="range"]::-moz-range-track { height: 3px; border-radius: 3px; background: var(--acr-beats-line2); }
  & input[type="range"]::-moz-range-progress { height: 3px; border-radius: 3px; background: var(--acr-beats-accent); }
  & input[type="range"]::-webkit-slider-thumb { -webkit-appearance: none; width: 12px; height: 12px; margin-top: -4.5px; border-radius: 50%; background: var(--acr-beats-ink); box-shadow: 0 0 0 3px var(--acr-beats-bg), 0 1px 4px oklch(0 0 0 / .6); }
  & input[type="range"]::-moz-range-thumb { width: 12px; height: 12px; border: 0; border-radius: 50%; background: var(--acr-beats-ink); }
}

/* ── transport ───────────────────────────────────────── */
.acr-beats .acr-beats-top { display: flex; align-items: center; gap: 16px; padding: 12px 16px; border-bottom: 1px solid var(--acr-beats-line); min-width: 0; }
.acr-beats .acr-beats-brand { display: flex; align-items: center; gap: 8px; font-weight: 780; font-size: 14px; letter-spacing: .02em; text-transform: uppercase;
  & svg { width: 20px; height: 20px; color: var(--acr-beats-accent); }
}
.acr-beats .acr-beats-transport { flex: 1; min-width: 0; display: flex; align-items: center; gap: 14px; justify-content: flex-end; }
.acr-beats .acr-beats-play {
  display: inline-flex; align-items: center; gap: 8px; height: 40px; padding: 0 16px 0 13px; border-radius: 11px; font-weight: 700; letter-spacing: .02em;
  background: linear-gradient(var(--acr-beats-accent), color-mix(in oklch, var(--acr-beats-accent) 82%, black)); color: oklch(0.2 0.03 50);
  box-shadow: inset 0 1px 0 oklch(1 0 0 / .35), 0 2px 0 color-mix(in oklch, var(--acr-beats-accent) 45%, black), 0 6px 18px -6px color-mix(in oklch, var(--acr-beats-accent) 70%, transparent);
  transition: transform .12s, box-shadow .12s, filter .2s;
  & svg { width: 18px; height: 18px; fill: currentColor; stroke: none; }
  & .acr-beats-i-stop { display: none; }
  &:active { transform: translateY(2px); box-shadow: inset 0 1px 0 oklch(1 0 0 / .3), 0 0 0 color-mix(in oklch, var(--acr-beats-accent) 45%, black); }
  &[aria-pressed="true"] { filter: saturate(1.2) brightness(1.05); & .acr-beats-i-play { display: none; } & .acr-beats-i-stop { display: block; } }
}
.acr-beats .acr-beats-lcd {
  position: relative; display: grid; grid-template-columns: auto 1fr; grid-template-rows: auto auto; column-gap: 12px; align-items: center; min-width: 190px; height: 44px; padding: 4px 12px; border-radius: 9px;
  background: oklch(0.16 0.025 150); color: oklch(0.88 0.16 145); box-shadow: inset 0 2px 6px oklch(0 0 0 / .6), inset 0 0 0 1px oklch(0 0 0 / .5), 0 1px 0 oklch(1 0 0 / .06);
  font-family: var(--acr-beats-mono); text-shadow: 0 0 8px oklch(0.8 0.18 145 / .55); overflow: hidden;
  &::after { content: ""; position: absolute; inset: 0; background: repeating-linear-gradient(transparent 0 2px, oklch(0 0 0 / .18) 2px 3px); pointer-events: none; }
}
.acr-beats .acr-beats-lcdpos { grid-row: 1 / 3; font-size: 22px; font-weight: 700; letter-spacing: .02em; font-variant-numeric: tabular-nums; }
.acr-beats .acr-beats-lcdpat { font-size: 10.5px; letter-spacing: .06em; text-transform: uppercase; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; opacity: .85; }
.acr-beats .acr-beats-meter { width: 100%; height: 8px; display: block; }
.acr-beats .acr-beats-bpm { display: flex; align-items: center; gap: 2px; }
.acr-beats .acr-beats-bpmval { display: grid; justify-items: center; min-width: 54px; padding: 2px 4px; border-radius: 8px; cursor: ns-resize; touch-action: none; user-select: none;
  & b { font: 700 20px/1 var(--acr-beats-mono); font-variant-numeric: tabular-nums; letter-spacing: -.02em; }
  & small { font-size: 9.5px; font-weight: 700; letter-spacing: .14em; color: var(--acr-beats-faint); }
  &:hover { background: var(--acr-beats-hover); }
}
.acr-beats .acr-beats-ib { display: grid; place-items: center; width: 28px; height: 28px; border-radius: 8px; color: var(--acr-beats-mute); transition: background-color .15s, color .15s, transform .3s var(--acr-beats-spring);
  &:hover:not(:disabled) { background: var(--acr-beats-hover); color: var(--acr-beats-ink); }
  &:active:not(:disabled) { transform: scale(.88); }
}
.acr-beats .acr-beats-tap { height: 28px; padding: 0 10px; margin-left: 4px; border-radius: 8px; font-weight: 700; font-size: 11px; letter-spacing: .08em; text-transform: uppercase; color: var(--acr-beats-mute);
  box-shadow: inset 0 0 0 1px var(--acr-beats-line2); transition: background-color .1s, color .1s;
  &:hover { color: var(--acr-beats-ink); }
  &.is-tap { background: var(--acr-beats-accent); color: oklch(0.2 0.03 50); box-shadow: none; }
}
.acr-beats .acr-beats-knobrow { display: grid; gap: 2px; width: 110px; font-size: 10.5px; font-weight: 650; letter-spacing: .06em; text-transform: uppercase; color: var(--acr-beats-faint);
  & span { display: flex; justify-content: space-between; }
  & output { font: 500 10.5px var(--acr-beats-mono); color: var(--acr-beats-ink); letter-spacing: 0; font-variant-numeric: tabular-nums; }
}

/* ── body ────────────────────────────────────────────── */
.acr-beats .acr-beats-body { min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr) 290px; grid-template-areas: "main side"; }
.acr-beats .acr-beats-main { grid-area: main; min-width: 0; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr) auto; gap: 10px; padding: 12px 16px 12px; }
.acr-beats .acr-beats-patbar { display: flex; align-items: center; gap: 8px; min-width: 0; }
.acr-beats .acr-beats-pats { display: flex; gap: 6px;
  & button { position: relative; display: grid; grid-template-columns: auto auto; align-items: baseline; gap: 6px; height: 32px; padding: 0 11px; border-radius: 9px; font-weight: 700; color: var(--acr-beats-mute);
    background: var(--acr-beats-panel); box-shadow: inset 0 1px 0 oklch(1 0 0 / .05), 0 1px 0 oklch(0 0 0 / .4), inset 0 0 0 1px var(--acr-beats-line); transition: color .15s, box-shadow .2s; }
  & button small { font-weight: 500; font-size: 11px; color: var(--acr-beats-faint); white-space: nowrap; }
  & button:hover { color: var(--acr-beats-ink); }
  & button[aria-checked="true"] { color: var(--acr-beats-ink); box-shadow: inset 0 0 0 1.5px var(--acr-beats-accent), 0 0 14px -4px color-mix(in oklch, var(--acr-beats-accent) 60%, transparent); & small { color: var(--acr-beats-mute); } }
  & button.is-queued { animation: acr-beats-blink .5s steps(2, jump-none) infinite; }
  & button i { position: absolute; top: 5px; right: 5px; width: 4px; height: 4px; border-radius: 50%; background: var(--acr-beats-faint); }
}
@keyframes acr-beats-blink { 50% { box-shadow: inset 0 0 0 1.5px var(--acr-beats-ink); color: var(--acr-beats-ink); } }
.acr-beats .acr-beats-queued { font: 11px var(--acr-beats-mono); color: var(--acr-beats-accent); white-space: nowrap; }
.acr-beats .acr-beats-pages { display: none; padding: 2px; gap: 2px; border-radius: 9px; background: var(--acr-beats-hover);
  & button { height: 26px; padding: 0 9px; border-radius: 7px; font: 600 11px var(--acr-beats-mono); color: var(--acr-beats-mute); }
  & button[aria-checked="true"] { background: var(--acr-beats-panel); color: var(--acr-beats-ink); box-shadow: inset 0 0 0 1px var(--acr-beats-line2); }
}
.acr-beats .acr-beats-chip { margin-left: auto; height: 28px; padding: 0 10px; border-radius: 8px; font-size: 12px; font-weight: 600; color: var(--acr-beats-mute); box-shadow: inset 0 0 0 1px var(--acr-beats-line2);
  &:hover:not(:disabled) { color: var(--acr-beats-ink); background: var(--acr-beats-hover); }
}

/* one column template on the grid; the LED row and every track row adopt it through subgrid */
.acr-beats .acr-beats-grid { min-height: 0; display: grid; grid-template-columns: var(--acr-beats-head, 168px) repeat(16, minmax(0, 1fr)); grid-template-rows: auto repeat(8, minmax(0, 1fr)); gap: 5px; }
.acr-beats .acr-beats-leds, .acr-beats .acr-beats-row { grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; }
@supports not (grid-template-columns: subgrid) {
  .acr-beats .acr-beats-leds, .acr-beats .acr-beats-row { grid-template-columns: var(--acr-beats-head, 168px) repeat(16, minmax(0, 1fr)); column-gap: 5px; }
}
.acr-beats .acr-beats-leds { padding-bottom: 1px;
  & i { justify-self: center; width: 8px; height: 4px; border-radius: 2px; background: var(--acr-beats-line2); transition: background-color .25s, box-shadow .25s; }
  & i:first-child { visibility: hidden; }
  & i.is-now { background: var(--acr-beats-accent); box-shadow: 0 0 10px var(--acr-beats-accent); transition: none; }
}
.acr-beats .acr-beats-row { min-height: 0; align-items: stretch; animation: acr-beats-in .5s var(--acr-beats-out) both; animation-delay: calc(var(--i) * 40ms); }
@keyframes acr-beats-in { from { opacity: 0; transform: translateX(-10px); } }
.acr-beats [role="gridcell"] { display: grid; min-width: 0; min-height: 0; }
.acr-beats [role="gridcell"]:is(:nth-child(6), :nth-child(10), :nth-child(14)) { margin-left: 5px; }
.acr-beats .acr-beats-head { display: grid; grid-template-columns: minmax(0, 1fr) 24px 24px; align-items: center; gap: 4px; padding-right: 8px; }
.acr-beats .acr-beats-name {
  display: flex; align-items: center; gap: 8px; height: 100%; min-height: 0; padding: 0 8px; border-radius: 8px; text-align: left; font-weight: 650; font-size: 12.5px; color: var(--acr-beats-mute); min-width: 0;
  transition: background-color .15s, color .15s;
  & i { width: 8px; height: 8px; border-radius: 50%; background: var(--tc); flex: none; box-shadow: 0 0 0 2px color-mix(in oklch, var(--tc) 25%, transparent); }
  & span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & small { display: none; margin-left: auto; font: 600 9.5px var(--acr-beats-mono); color: var(--acr-beats-faint); letter-spacing: .04em; }
  &:hover { background: var(--acr-beats-hover); color: var(--acr-beats-ink); }
  &[aria-current="true"] { background: color-mix(in oklch, var(--tc) 14%, transparent); color: var(--acr-beats-ink); box-shadow: inset 2px 0 0 var(--tc); }
}
.acr-beats .acr-beats-ms { height: 24px; border-radius: 6px; font: 700 10px var(--acr-beats-mono); color: var(--acr-beats-faint); background: var(--acr-beats-well); box-shadow: inset 0 1px 2px oklch(0 0 0 / .5);
  &:hover { color: var(--acr-beats-ink); }
  &[data-mute][aria-pressed="true"] { background: oklch(0.62 0.17 28); color: white; box-shadow: 0 0 10px -2px oklch(0.62 0.17 28); }
  &[data-solo][aria-pressed="true"] { background: oklch(0.82 0.15 92); color: oklch(0.2 0.03 80); box-shadow: 0 0 10px -2px oklch(0.82 0.15 92); }
}
.acr-beats .acr-beats-row.is-silent [role="gridcell"] { opacity: .32; }
.acr-beats .acr-beats-pad {
  position: relative; width: 100%; height: 100%; min-height: 0; border-radius: 7px; cursor: pointer; touch-action: none;
  background: var(--acr-beats-well); box-shadow: inset 0 1px 3px oklch(0 0 0 / .55), inset 0 0 0 1px oklch(1 0 0 / .03);
  transition: background-color .12s, box-shadow .2s, transform .25s var(--acr-beats-spring);
  &.is-beat { background: color-mix(in oklch, var(--acr-beats-well) 86%, var(--acr-beats-ink)); }
  &:hover { box-shadow: inset 0 1px 3px oklch(0 0 0 / .4), inset 0 0 0 1px color-mix(in oklch, var(--tc) 50%, transparent); }
  &[aria-pressed="true"] { background: linear-gradient(color-mix(in oklch, var(--tc) 92%, white), var(--tc)); box-shadow: inset 0 1px 0 oklch(1 0 0 / .45), 0 0 12px -3px var(--tc), 0 1px 2px oklch(0 0 0 / .5); }
  &[data-acc="1"]::after { content: ""; position: absolute; top: 4px; right: 4px; width: 5px; height: 5px; border-radius: 50%; background: oklch(0.2 0.02 60 / .75); box-shadow: 0 0 0 1.5px oklch(1 0 0 / .5); }
  &[aria-pressed="false"][data-acc="1"]::after { display: none; }
  &[aria-pressed="false"]:active { transform: scale(.94); }
  &.is-now { box-shadow: inset 0 0 0 1.5px oklch(1 0 0 / .55), inset 0 1px 3px oklch(0 0 0 / .4); }
  &[aria-pressed="true"].is-now { filter: brightness(1.18) saturate(1.1); box-shadow: inset 0 1px 0 oklch(1 0 0 / .6), 0 0 22px -2px var(--tc); }
  &:focus-visible { outline-offset: 1px; }
}
.acr-beats .acr-beats-keys { display: flex; flex-wrap: wrap; gap: 4px 14px; justify-content: center; font-size: 11px; color: var(--acr-beats-faint);
  & span { display: inline-flex; gap: 4px; align-items: center; white-space: nowrap; }
}

/* ── voice side ──────────────────────────────────────── */
