/* ── Ostinato · step sequencer drum machine ────────────────────────────
   Every drum is synthesised with Web Audio oscillators, noise and
   filters — no samples. Timing uses the lookahead pattern: a 25 ms timer
   schedules any step due in the next 100 ms at an exact AudioContext
   time, while a rAF loop only paints the playhead from a queue of
   (step, time) notes. The voice waveform is rendered by an
   OfflineAudioContext running the very same voice code. The clock is
   performance.now(), so the sequencer still runs (silently) wherever
   audio cannot start. */
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const clamp = (v, a, b) => v < a ? a : v > b ? b : v;

const TRACKS = [
  { name: 'Kick', short: 'BD', sub: 'sine · pitch sweep · click' },
  { name: 'Snare', short: 'SD', sub: 'triangle body · high-passed noise' },
  { name: 'Clap', short: 'CP', sub: 'band-passed noise, three bursts' },
  { name: 'Closed hat', short: 'CH', sub: 'six square partials · HP' },
  { name: 'Open hat', short: 'OH', sub: 'six squares · choked by CH' },
  { name: 'Low tom', short: 'LT', sub: 'sine · pitch drop' },
  { name: 'Rim', short: 'RS', sub: 'triangle + square click' },
  { name: 'Cowbell', short: 'CB', sub: '587 + 845 Hz squares · BP' },
];
const KNOBS = [['tune', 'Tune', -12, 12, v => (v > 0 ? '+' : '') + v + ' st'], ['decay', 'Decay', 0, 100, v => Math.round(Math.pow(2, (v - 50) / 30) * 100) + '%'], ['tone', 'Tone', 0, 100, v => v + ''], ['level', 'Level', 0, 100, v => v + '']];
const params = TRACKS.map((t, i) => ({ tune: 0, decay: 50, tone: [55, 40, 50, 45, 50, 40, 50, 50][i], level: [92, 78, 70, 58, 52, 74, 60, 50][i] }));
const P = s => [...s].map(c => c === 'X' ? 2 : c === 'x' ? 1 : 0);
const PATS = [
  { name: 'Night Bus', rows: ['X.....x.X..x....', '....X.......X...', '....x.........x.', 'x.xx..x.x.xx..x.', '.....x.......x..', '...........x..x.', '...x......x.....', '................'] },
  { name: 'Floor', rows: ['X...X...X...X...', '................', '....X.......X...', 'x..xx..xx..xx..x', '..X...X...X...X.', '................', '...x.....x......', '..........x.....'] },
  { name: 'Clave', rows: ['X..x..x.X..x..x.', '................', '................', 'x.x.x.x.x.x.x.x.', '................', '......x.......x.', 'X..x..x...x.x...', '........x.......'] },
  { name: 'Sketch', rows: Array(8).fill('................') },
].map(p => ({ name: p.name, rows: p.rows.map(P) }));
const S = { pat: 0, next: -1, sel: 0, bpm: 112, swing: .04, vol: .8, mute: Array(8).fill(false), solo: Array(8).fill(false), playing: false, page: 0, ek: 5, er: 0 };

/* ── history (pattern edits) ───────────────────────── */
const hist = []; let hi = -1;
const snap = () => JSON.stringify(PATS.map(p => p.rows));
function commit() { const s = snap(); if (hi >= 0 && hist[hi] === s) return; hist.length = hi + 1; hist.push(s); hi = hist.length - 1; syncUndo(); }
function restore(i) { hi = i; JSON.parse(hist[i]).forEach((rows, k) => { PATS[k].rows = rows; }); renderGrid(); syncUndo(); }
function syncUndo() {
  const u = $('[data-act="undo"]'), r = $('[data-act="redo"]');
  u.disabled = hi <= 0; u.title = u.disabled ? 'Nothing to undo' : 'Undo (⌘Z)';
  r.disabled = hi >= hist.length - 1; r.title = r.disabled ? 'Nothing to redo' : 'Redo (⇧⌘Z)';
}

/* ── toast ─────────────────────────────────────────── */
const toastEl = $('[data-toast]'); let toastT = 0;
function toast(m) { toastEl.textContent = m; toastEl.classList.add('is-on'); clearTimeout(toastT); toastT = setTimeout(() => toastEl.classList.remove('is-on'), 1800); }

/* ── audio ─────────────────────────────────────────── */
let ac = null, master = null, analyser = null, openHat = null, NOISE = null;
function noiseBuf() {
  if (NOISE) return NOISE;
  try { NOISE = new AudioBuffer({ length: 44100, sampleRate: 44100, numberOfChannels: 1 }); } catch (e) { return null; }
  const d = NOISE.getChannelData(0); let s = 7; for (let i = 0; i < d.length; i++) { s = (s * 16807) % 2147483647; d[i] = s / 1073741823.5 - 1; }
  return NOISE;
}
function ensureAudio() {
  if (ac) { if (ac.state === 'suspended') { const p = ac.resume(); if (p && p.catch) p.catch(() => {}); } return ac; }
  const AC = window.AudioContext || window.webkitAudioContext; if (!AC) return null;
  try { ac = new AC(); } catch (e) { ac = null; return null; }
  master = ac.createGain(); master.gain.value = S.vol;
  const comp = ac.createDynamicsCompressor(); comp.threshold.value = -12; comp.ratio.value = 3; comp.attack.value = .003; comp.release.value = .12;
  analyser = ac.createAnalyser(); analyser.fftSize = 512;
  master.connect(comp); comp.connect(analyser); analyser.connect(ac.destination);
  const p = ac.resume(); if (p && p.catch) p.catch(() => {});
  setTimeout(watchdog, 1500);
  return ac;
}
const audioLive = () => ac && ac.state === 'running';
function voice(ctx, out, ti, t, vel, prm) {
  const p = prm || params[ti], ratio = Math.pow(2, p.tune / 12), dm = Math.pow(2, (p.decay - 50) / 30), x = p.tone / 100;
  const lv = Math.max(.0003, p.level / 100 * vel);
  const g = ctx.createGain(); g.connect(out);
  const bq = (type, f, q) => { const b = ctx.createBiquadFilter(); b.type = type; b.frequency.value = f; if (q) b.Q.value = q; return b; };
  const env = (node, peak, dur, att = .002) => { node.gain.setValueAtTime(.0001, t); node.gain.exponentialRampToValueAtTime(Math.max(.0003, peak), t + att); node.gain.exponentialRampToValueAtTime(.0001, t + dur); };
  const noise = () => { const s = ctx.createBufferSource(); s.buffer = noiseBuf(); return s; };
  const osc = (type, f) => { const o = ctx.createOscillator(); o.type = type; o.frequency.setValueAtTime(f, t); return o; };
  if (ti === 0) {
    const o = osc('sine', (96 + 130 * x) * ratio), a = ctx.createGain();
    o.frequency.exponentialRampToValueAtTime(44 * ratio, t + .07 + .05 * (1 - x));
    env(a, lv, .44 * dm); o.connect(a).connect(g); o.start(t); o.stop(t + .46 * dm + .05);
    if (noiseBuf()) { const n = noise(), ng = ctx.createGain(); env(ng, lv * .3 * x, .014); n.connect(bq('highpass', 2600)).connect(ng).connect(g); n.start(t); n.stop(t + .03); }
  } else if (ti === 1) {
    const o = osc('triangle', 192 * ratio), a = ctx.createGain(); o.frequency.exponentialRampToValueAtTime(148 * ratio, t + .1);
    env(a, lv * (.8 - .45 * x), .15 * dm); o.connect(a).connect(g); o.start(t); o.stop(t + .2 * dm + .03);
    if (noiseBuf()) { const n = noise(), ng = ctx.createGain(); env(ng, lv * (.35 + .55 * x), .2 * dm); n.connect(bq('highpass', 1400 * ratio)).connect(ng).connect(g); n.start(t); n.stop(t + .26 * dm); }
  } else if (ti === 2) {
    if (noiseBuf()) {
      const n = noise(), ng = ctx.createGain(); ng.gain.setValueAtTime(.0001, t);
      [0, .011, .022].forEach(d => { ng.gain.setValueAtTime(lv, t + d); ng.gain.exponentialRampToValueAtTime(lv * .18, t + d + .009); });
      ng.gain.setValueAtTime(lv * .85, t + .031); ng.gain.exponentialRampToValueAtTime(.0001, t + .031 + .2 * dm);
      n.connect(bq('bandpass', (850 + 950 * x) * ratio, 1.1)).connect(ng).connect(g); n.start(t); n.stop(t + .26 * dm + .05);
    }
  } else if (ti === 3 || ti === 4) {
    const bp = bq('bandpass', 10000, .8), hp = bq('highpass', 6000 + 3500 * x), a = ctx.createGain(), dur = ti === 3 ? .055 * dm : .4 * dm;
    env(a, lv * .5, dur);
    [2, 3, 4.16, 5.43, 6.79, 8.21].forEach(m => { const o = osc('square', 40 * m * ratio); o.connect(bp); o.start(t); o.stop(t + dur + .03); });
    bp.connect(hp).connect(a).connect(g);
    if (ctx === ac) {
      if (ti === 3 && openHat) { try { openHat.gain.cancelScheduledValues(t); openHat.gain.setTargetAtTime(.0001, t, .006); } catch (e) {} openHat = null; }
      if (ti === 4) openHat = a;
    }
  } else if (ti === 5) {
    const o = osc('sine', 142 * ratio), a = ctx.createGain(); o.frequency.exponentialRampToValueAtTime(78 * ratio, t + .22);
    env(a, lv, .4 * dm); o.connect(a).connect(g); o.start(t); o.stop(t + .42 * dm + .05);
    if (noiseBuf()) { const n = noise(), ng = ctx.createGain(); env(ng, lv * .16, .05); n.connect(bq('lowpass', 900 + 2200 * x)).connect(ng).connect(g); n.start(t); n.stop(t + .08); }
  } else if (ti === 6) {
    const o = osc('triangle', 1700 * ratio), o2 = osc('square', 480 * ratio), hp = bq('highpass', 300 + 700 * x), a = ctx.createGain();
    env(a, lv * .55, .04 * dm); o.connect(hp); o2.connect(hp); hp.connect(a).connect(g);
    [o, o2].forEach(z => { z.start(t); z.stop(t + .06 * dm + .03); });
  } else {
    const bp = bq('bandpass', 2400 * ratio + 1400 * x, 1.2), a = ctx.createGain();
    a.gain.setValueAtTime(.0001, t); a.gain.exponentialRampToValueAtTime(lv * .5, t + .002); a.gain.exponentialRampToValueAtTime(lv * .18, t + .05); a.gain.exponentialRampToValueAtTime(.0001, t + .36 * dm);
    [587, 845].forEach(f => { const o = osc('square', f * ratio); o.connect(bp); o.start(t); o.stop(t + .38 * dm + .03); });
    bp.connect(a).connect(g);
  }
}

/* ── grid markup ───────────────────────────────────── */
const gridEl = $('[data-grid]');
gridEl.innerHTML = '<div class="acr-beats-leds" aria-hidden="true" data-leds><i></i>' + Array.from({ length: 16 }, () => '<i></i>').join('') + '</div>' + TRACKS.map((t, r) => '<div class="acr-beats-row" role="row" data-row="' + r + '" style="--i:' + r + ';--tc:var(--acr-beats-t' + r + ')">' +
  '<div class="acr-beats-head" role="rowheader"><button class="acr-beats-name" data-sel="' + r + '" title="Select and audition (' + (r + 1) + ')"><i></i><span>' + t.name + '</span><small>' + t.short + '</small></button>' +
  '<button class="acr-beats-ms" data-mute="' + r + '" aria-pressed="false" aria-label="Mute ' + t.name + '" title="Mute">M</button><button class="acr-beats-ms" data-solo="' + r + '" aria-pressed="false" aria-label="Solo ' + t.name + '" title="Solo">S</button></div>' +
  Array.from({ length: 16 }, (_, s) => '<div role="gridcell"><button class="acr-beats-pad' + (s % 4 === 0 ? ' is-beat' : '') + '" data-r="' + r + '" data-s="' + s + '" aria-pressed="false" tabindex="' + (r === 0 && s === 0 ? 0 : -1) + '" aria-label="' + t.name + ', step ' + (s + 1) + '"></button></div>').join('') + '</div>').join('');
const pads = TRACKS.map((_, r) => $$('[data-r="' + r + '"]'));
const leds = $$('[data-leds] i').slice(1);
$('[data-pats]').innerHTML = PATS.map((p, i) => '<button role="radio" aria-checked="' + (i === 0) + '" data-pat="' + i + '" title="Pattern ' + 'ABCD'[i] + ' — ' + p.name + '">' + 'ABCD'[i] + '<small>' + p.name + '</small></button>').join('');
$('[data-knobs]').innerHTML = KNOBS.map(([k, label, min, max]) => '<div class="acr-beats-knob"><div class="acr-beats-dial" role="slider" tabindex="0" data-knob="' + k + '" aria-label="' + label + ', drag up or down" aria-valuemin="' + min + '" aria-valuemax="' + max + '"><svg viewBox="0 0 60 60" aria-hidden="true"><path d="M14.6 45.4A21.5 21.5 0 1 1 45.4 45.4" stroke="currentColor" stroke-opacity=".14" stroke-width="3"/><path data-arc d="" stroke="var(--tc)" stroke-width="3"/></svg></div><output data-kout="' + k + '"></output><span>' + label + '</span></div>').join('');

/* ── render state ──────────────────────────────────── */
const audible = r => !S.mute[r] && (!S.solo.some(Boolean) || S.solo[r]);
function renderGrid() {
