/* ── Stipple · pixel icon editor ───────────────────────────────────────
   Frames are flat arrays of hex strings (null = transparent). Tools are
   the classic raster algorithms — Bresenham lines (also used to join
   fast pencil moves), an inside-test ellipse, a stack flood fill — with
   optional mirror painting, onion skin and an animated preview that
   pauses off screen. Export merges same-coloured pixels into rectangles
   greedily and writes one <path> per colour. */
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const clamp = (v, a, b) => v < a ? a : v > b ? b : v;
const esc = s => String(s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');

const PAL = ['#1E1B24', '#3B3045', '#6B6F7A', '#A7ABB3', '#F4F1E8', '#FFF2B8', '#FFD45E', '#FF9A3C', '#E2483D', '#8A5A3C', '#C08552', '#5AA469', '#2A5C45', '#4FB3C8', '#3E5C9A', '#B35C9B'];
