.acr-type {
  /* re-theme with these four */
  --acr-type-bg: oklch(0.966 0.014 86);
  --acr-type-paper: oklch(0.988 0.008 88);
  --acr-type-ink: oklch(0.21 0.012 60);
  --acr-type-accent: oklch(0.58 0.19 33);
  /* derived */
  --acr-type-line: color-mix(in oklch, var(--acr-type-ink) 11%, transparent);
  --acr-type-line2: color-mix(in oklch, var(--acr-type-ink) 19%, transparent);
  --acr-type-hover: color-mix(in oklch, var(--acr-type-ink) 5%, transparent);
  --acr-type-mute: color-mix(in oklch, var(--acr-type-ink) 66%, var(--acr-type-bg));
  --acr-type-faint: color-mix(in oklch, var(--acr-type-ink) 44%, var(--acr-type-bg));
  --acr-type-acc-soft: color-mix(in oklch, var(--acr-type-accent) 11%, var(--acr-type-paper));
  --acr-type-ease: cubic-bezier(.2, .8, .2, 1);
  --acr-type-out: cubic-bezier(.16, 1, .3, 1);
  --acr-type-spring: linear(0, 0.12 6%, 0.46 14%, 0.86 24%, 1.04 32%, 1.07 38%, 1.03 48%, 0.996 62%, 1);
  --acr-type-mono: ui-monospace, Menlo, monospace;
  --acr-type-ui: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;

  position: relative; width: 100%; height: var(--acr-type-h, 680px); box-sizing: border-box;
  container-type: inline-size; container-name: acr-type; overflow: clip; isolation: isolate;
  display: grid; grid-template-rows: auto minmax(0, 1fr) auto;
  border-radius: 16px; background: var(--acr-type-bg); color: var(--acr-type-ink); color-scheme: light;
  accent-color: var(--acr-type-ink); box-shadow: inset 0 0 0 1px var(--acr-type-line);
  font: 12.5px/1.45 var(--acr-type-ui); -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--acr-type-accent); outline-offset: 2px; }
  & button, & input { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & button:disabled { cursor: not-allowed; opacity: .4; }
  & h1, & h2, & h3, & p, & ul, & dl, & dd, & blockquote { margin: 0; padding: 0; }
  & ul { list-style: none; }
  & [hidden] { display: none !important; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { display: inline-grid; place-items: center; min-width: 18px; height: 18px; padding: 0 5px; border-radius: 5px; font: 600 10px/1 var(--acr-type-mono); }
}

/* ── top ─────────────────────────────────────────────── */
.acr-type .acr-type-top { display: flex; align-items: center; gap: 18px; padding: 10px 12px 10px 20px; border-bottom: 1px solid var(--acr-type-line); min-width: 0; }
.acr-type .acr-type-brand { display: flex; align-items: baseline; gap: 8px; white-space: nowrap;
  & b { font: italic 700 19px/1 ui-serif, Georgia, serif; letter-spacing: -.02em; }
  & span { font-size: 11px; letter-spacing: .12em; text-transform: uppercase; color: var(--acr-type-faint); font-weight: 600; }
}
.acr-type .acr-type-tabs { display: flex; gap: 2px; padding: 3px; border-radius: 10px; background: var(--acr-type-hover);
  & button { height: 28px; padding: 0 12px; border-radius: 8px; font-weight: 600; color: var(--acr-type-mute); transition: background-color .2s, color .2s; }
  & button:hover { color: var(--acr-type-ink); }
  & button[aria-selected="true"] { background: var(--acr-type-paper); color: var(--acr-type-ink); box-shadow: 0 1px 2px oklch(0.2 0.02 60 / .15), inset 0 0 0 1px var(--acr-type-line); }
}
.acr-type .acr-type-acts { margin-left: auto; display: flex; align-items: center; gap: 6px; }
.acr-type .acr-type-ib { display: grid; place-items: center; width: 32px; height: 32px; border-radius: 9px; color: var(--acr-type-mute); transition: background-color .15s, color .15s, transform .3s var(--acr-type-spring);
  &:hover:not(:disabled) { background: var(--acr-type-hover); color: var(--acr-type-ink); }
  &:active:not(:disabled) { transform: scale(.9); }
  &[aria-pressed="true"] { color: var(--acr-type-accent); & svg { fill: currentColor; } }
}
.acr-type .acr-type-btn { display: inline-flex; align-items: center; gap: 7px; height: 32px; padding: 0 11px; border-radius: 9px; font-weight: 600; white-space: nowrap; background: var(--acr-type-paper); box-shadow: inset 0 0 0 1px var(--acr-type-line2);
  &:hover { background: var(--acr-type-hover); }
}
.acr-type .acr-type-primary { display: inline-flex; align-items: center; gap: 8px; height: 32px; padding: 0 8px 0 12px; border-radius: 9px; font-weight: 650; white-space: nowrap;
  background: var(--acr-type-ink); color: var(--acr-type-paper); box-shadow: 0 1px 2px oklch(0 0 0 / .2);
  transition: transform .35s var(--acr-type-spring), background-color .2s;
  & kbd { background: oklch(1 0 0 / .15); color: oklch(1 0 0 / .8); }
  & svg { transform: rotate(var(--r, 0deg)); transition: transform .6s var(--acr-type-spring); }
  &:hover { background: color-mix(in oklch, var(--acr-type-ink) 85%, var(--acr-type-accent)); }
  &:active { transform: scale(.96); }
}

/* ── body ────────────────────────────────────────────── */
.acr-type .acr-type-body { min-height: 0; display: grid; grid-template-columns: 262px minmax(0, 1fr) 272px; grid-template-areas: "left center right"; }
.acr-type .acr-type-left, .acr-type .acr-type-right { min-height: 0; background: var(--acr-type-paper); }
.acr-type .acr-type-left { grid-area: left; display: grid; grid-template-rows: auto auto minmax(0, 1fr); border-right: 1px solid var(--acr-type-line); }
.acr-type .acr-type-right { grid-area: right; overflow-y: auto; overscroll-behavior: contain; scrollbar-width: thin; border-left: 1px solid var(--acr-type-line); }
.acr-type .acr-type-roles { display: grid; gap: 8px; padding: 12px 12px 10px; border-bottom: 1px solid var(--acr-type-line); }
.acr-type .acr-type-role { display: grid; grid-template-columns: 1fr 1fr; gap: 6px;
  & button { display: grid; gap: 1px; text-align: left; padding: 7px 10px; border-radius: 10px; min-width: 0; box-shadow: inset 0 0 0 1px var(--acr-type-line); transition: box-shadow .2s, background-color .2s; }
  & small { font-size: 10px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--acr-type-faint); }
  & b { font-weight: 620; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & button:hover { background: var(--acr-type-hover); }
  & button[aria-checked="true"] { background: var(--acr-type-acc-soft); box-shadow: inset 0 0 0 1.5px var(--acr-type-accent); & small { color: var(--acr-type-accent); } }
}
.acr-type .acr-type-locks { display: flex; gap: 6px; }
.acr-type .acr-type-lock { flex: 1; display: inline-flex; align-items: center; justify-content: center; gap: 6px; height: 26px; border-radius: 7px; font-size: 11.5px; font-weight: 600; color: var(--acr-type-faint);
  & svg { width: 13px; height: 13px; }
  &:hover { color: var(--acr-type-ink); background: var(--acr-type-hover); }
  &[aria-pressed="true"] { color: var(--acr-type-ink); background: var(--acr-type-hover); box-shadow: inset 0 0 0 1px var(--acr-type-line2); & svg { color: var(--acr-type-accent); } }
}
.acr-type .acr-type-cats { display: flex; flex-wrap: wrap; gap: 4px; padding: 10px 12px; border-bottom: 1px solid var(--acr-type-line);
  & button { height: 24px; padding: 0 9px; border-radius: 99px; font-size: 11.5px; font-weight: 600; color: var(--acr-type-mute); box-shadow: inset 0 0 0 1px var(--acr-type-line); }
  & button:hover { color: var(--acr-type-ink); }
  & button[aria-checked="true"] { background: var(--acr-type-ink); color: var(--acr-type-paper); box-shadow: none; }
}
.acr-type .acr-type-fonts { min-height: 0; overflow-y: auto; overscroll-behavior: contain; scrollbar-width: thin; padding: 6px; display: grid; align-content: start; gap: 2px; }
.acr-type .acr-type-font {
  display: grid; grid-template-columns: 44px minmax(0, 1fr) auto; align-items: center; gap: 10px; padding: 7px 8px; border-radius: 10px; text-align: left;
  transition: background-color .15s; animation: acr-type-in .35s var(--acr-type-out) both; animation-delay: calc(var(--i, 0) * 18ms);
  & .acr-type-ag { font-size: 26px; line-height: 1; text-align: center; font-family: var(--f); }
  & .acr-type-fname { display: grid; min-width: 0; }
  & .acr-type-fname b { font-family: var(--f); font-size: 15px; font-weight: 400; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .acr-type-fname small { font-size: 10.5px; color: var(--acr-type-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .acr-type-fname small.is-miss { color: oklch(0.55 0.15 50); }
  & .acr-type-tags { display: flex; gap: 3px; }
  & .acr-type-tags i { display: grid; place-items: center; width: 18px; height: 18px; border-radius: 5px; font: 700 10px var(--acr-type-mono); font-style: normal; background: var(--acr-type-hover); color: var(--acr-type-faint); }
  & .acr-type-tags i.is-h, & .acr-type-tags i.is-b { background: var(--acr-type-ink); color: var(--acr-type-paper); }
  &:hover { background: var(--acr-type-hover); }
  &[aria-selected="true"] { background: var(--acr-type-acc-soft); box-shadow: inset 2px 0 0 var(--acr-type-accent); }
}
@keyframes acr-type-in { from { opacity: 0; transform: translateY(4px); } }

/* ── specimen ────────────────────────────────────────── */
.acr-type .acr-type-center { grid-area: center; position: relative; min-width: 0; min-height: 0; overflow-y: auto; overscroll-behavior: contain; scrollbar-width: thin; container-type: inline-size; container-name: acr-type-pane;
  background: var(--acr-type-paper); }
.acr-type .acr-type-spec {
  --h: Georgia, serif; --b: system-ui, sans-serif; --lh: 1.55; --hw: 600; --tr: -0.015em; --measure: 64ch;
  --s-1: 14px; --s0: 17px; --s1: 21px; --s2: 26px; --s3: 32px; --s4: 40px; --s5: 50px; --s6: 62px;
  padding: clamp(18px, 5cqi, 48px) clamp(18px, 6cqi, 60px) 64px; font-family: var(--b); font-size: var(--s0); line-height: var(--lh); color: var(--acr-type-ink);
  & h1, & h2, & h3, & blockquote, & .acr-type-mast { font-family: var(--h); font-weight: var(--hw); letter-spacing: var(--tr); text-wrap: balance; }
  & h1 { font-size: var(--s5); line-height: 1.06; }
  & h2 { font-size: var(--s3); line-height: 1.15; margin-top: 1.3em; }
  & h3 { font-size: var(--s1); line-height: 1.2; }
  & p { text-wrap: pretty; }
  & [style*="--i"] { animation: acr-type-rise .55s var(--acr-type-out) both; animation-delay: calc(var(--i) * 45ms); }
  &.is-swap [style*="--i"] { animation: acr-type-rise .55s var(--acr-type-out) both; animation-delay: calc(var(--i) * 45ms); }
}
@keyframes acr-type-rise { from { opacity: 0; transform: translateY(10px); filter: blur(3px); } }
.acr-type .acr-type-mast { display: flex; justify-content: space-between; gap: 12px; padding-bottom: 10px; margin-bottom: 1.6em; border-bottom: 3px double var(--acr-type-line2); font-size: var(--s-1); font-weight: 400; text-transform: uppercase; letter-spacing: .12em; }
.acr-type .acr-type-kicker { font-size: var(--s-1); font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--acr-type-accent); margin-bottom: .6em; }
