/* ── Typecase · system-font pairing ────────────────────────────────────
   Only fonts already on the reader's machine. Each stack is probed with
   canvas measureText against a monospace fallback, so the list says
   honestly which face is installed and what it falls back to; the same
   canvas measures x-height (actualBoundingBoxAscent of "x" per em) to
   judge whether two faces sit together. The modular scale is written as
   clamp() steps — cqi-based in the preview pane, vw-based in the export
   — and a live meter counts characters per line from the real
   paragraph width and the body font's average glyph width. */
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
