const clamp = (v, a, b) => v < a ? a : v > b ? b : v;
const esc = s => String(s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');

const FONTS = [
  ['iowan', 'Iowan Old Style', 'serif', '"Iowan Old Style", "Palatino Linotype", Palatino, serif'],
  ['charter', 'Charter', 'serif', 'Charter, "Bitstream Charter", "Sitka Text", Cambria, serif'],
  ['georgia', 'Georgia', 'serif', 'Georgia, "Times New Roman", serif'],
  ['palatino', 'Palatino', 'serif', 'Palatino, "Palatino Linotype", "Book Antiqua", serif'],
  ['baskerville', 'Baskerville', 'serif', 'Baskerville, "Baskerville Old Face", "Libre Baskerville", serif'],
  ['hoefler', 'Hoefler Text', 'serif', '"Hoefler Text", Garamond, "Times New Roman", serif'],
  ['uiserif', 'System Serif', 'serif', 'ui-serif, "New York", Georgia, serif'],
  ['times', 'Times New Roman', 'serif', '"Times New Roman", Times, serif'],
  ['didot', 'Didot', 'display', 'Didot, "Bodoni 72", "Bodoni MT", serif'],
  ['futura', 'Futura', 'display', 'Futura, "Century Gothic", "Trebuchet MS", sans-serif'],
  ['system', 'System UI', 'sans', 'system-ui, -apple-system, "Segoe UI", Roboto, sans-serif'],
  ['helvetica', 'Helvetica Neue', 'sans', '"Helvetica Neue", Helvetica, Arial, sans-serif'],
  ['avenir', 'Avenir Next', 'sans', '"Avenir Next", Avenir, "Segoe UI", sans-serif'],
  ['gill', 'Gill Sans', 'sans', '"Gill Sans", "Gill Sans MT", Calibri, sans-serif'],
  ['optima', 'Optima', 'sans', 'Optima, Candara, "Segoe UI", sans-serif'],
  ['verdana', 'Verdana', 'sans', 'Verdana, Geneva, sans-serif'],
  ['trebuchet', 'Trebuchet MS', 'sans', '"Trebuchet MS", "Lucida Grande", sans-serif'],
  ['rounded', 'System Rounded', 'rounded', 'ui-rounded, "SF Pro Rounded", "Arial Rounded MT Bold", system-ui, sans-serif'],
  ['typewriter', 'American Typewriter', 'slab', '"American Typewriter", "Courier New", serif'],
  ['rockwell', 'Rockwell', 'slab', 'Rockwell, "Rockwell Nova", "Roboto Slab", Georgia, serif'],
  ['mono', 'System Mono', 'mono', 'ui-monospace, "SF Mono", Menlo, Consolas, monospace'],
  ['courier', 'Courier New', 'mono', '"Courier New", Courier, monospace'],
].map(([id, name, cat, stack]) => ({ id, name, cat, stack }));
const F = id => FONTS.find(f => f.id === id);
const CATS = [['all', 'All'], ['serif', 'Serif'], ['sans', 'Sans'], ['display', 'Display'], ['slab', 'Slab'], ['rounded', 'Rounded'], ['mono', 'Mono']];
const CATNAME = { serif: 'serif', sans: 'sans', display: 'display face', slab: 'slab serif', rounded: 'rounded sans', mono: 'monospace' };
const RATIOS = [['Minor second', 1.067], ['Major second', 1.125], ['Minor third', 1.2], ['Major third', 1.25], ['Perfect fourth', 1.333], ['Aug. fourth', 1.414], ['Perfect fifth', 1.5], ['Golden', 1.618]];
const PAIRS = [['iowan', 'system', 1.333], ['didot', 'avenir', 1.5], ['futura', 'georgia', 1.25], ['helvetica', 'charter', 1.25], ['baskerville', 'gill', 1.333], ['uiserif', 'system', 1.25], ['typewriter', 'helvetica', 1.2], ['rounded', 'iowan', 1.25], ['optima', 'palatino', 1.2], ['hoefler', 'avenir', 1.333], ['gill', 'georgia', 1.25], ['mono', 'system', 1.2], ['rockwell', 'verdana', 1.25], ['avenir', 'hoefler', 1.414]];
const S = { h: 'iowan', b: 'system', ratio: 1.333, base: 17, lh: 1.55, measure: 64, hw: 600, track: -0.015, role: 'h', cat: 'all', lockH: false, lockB: false, spec: 'article', spin: 0,
  favs: [{ h: 'didot', b: 'avenir', ratio: 1.5 }, { h: 'futura', b: 'georgia', ratio: 1.25 }, { h: 'baskerville', b: 'gill', ratio: 1.333 }] };

/* ── font probing on a canvas ──────────────────────── */
const probe = document.createElement('canvas').getContext('2d');
const TEST = 'mmmmmmmmmmlliWQ@#gfi&8';
const famList = stack => stack.split(',').map(s => s.trim());
function hasFamily(fam) {
  if (/^(serif|sans-serif|monospace)$/.test(fam)) return true;
  probe.font = '72px monospace'; const a = probe.measureText(TEST).width;
  probe.font = '72px ' + fam + ', monospace'; const b = probe.measureText(TEST).width;
  if (Math.abs(a - b) > .5) return true;
  probe.font = '72px serif'; const c = probe.measureText(TEST).width;
  probe.font = '72px ' + fam + ', serif'; return Math.abs(probe.measureText(TEST).width - c) > .5 && fam !== 'monospace';
}
FONTS.forEach(f => {
  const fams = famList(f.stack);
  f.ok = hasFamily(fams[0]);
  f.uses = f.ok ? null : (fams.slice(1).find(x => hasFamily(x)) || fams[fams.length - 1]).replace(/"/g, '');
  probe.font = '200px ' + f.stack;
  const mx = probe.measureText('x'), mH = probe.measureText('H'), avg = probe.measureText('the quick brown fox jumps over a lazy dog').width / 41;
  f.xh = (mx.actualBoundingBoxAscent || 104) / 200; f.cap = (mH.actualBoundingBoxAscent || 140) / 200; f.avg = avg / 200;
});

/* ── history & toast ───────────────────────────────── */
const KEYS = ['h', 'b', 'ratio', 'base', 'lh', 'measure', 'hw', 'track'];
const hist = []; let hi = -1;
const snap = () => JSON.stringify(KEYS.map(k => S[k]));
function commit(key) {
  const s = snap(), now = performance.now(); if (hi >= 0 && hist[hi].s === s) return;
  hist.length = hi + 1;
  if (key && hi > 0 && hist[hi].key === key && now - hist[hi].t < 1200) hist[hi] = { s, key, t: now }; else { hist.push({ s, key, t: now }); hi = hist.length - 1; }
  syncUndo();
}
function syncUndo() { const u = $('[data-act="undo"]'); u.disabled = hi <= 0; u.title = u.disabled ? 'Nothing to undo' : 'Undo (⌘Z)'; }
const toastEl = $('[data-toast]'); let toastT = 0;
function toast(m) { toastEl.textContent = m; toastEl.classList.add('is-on'); clearTimeout(toastT); toastT = setTimeout(() => toastEl.classList.remove('is-on'), 1900); }

/* ── type scale ────────────────────────────────────── */
function stepPx(s) { const mn = S.base * .88 * Math.pow(1 + (S.ratio - 1) * .82, s), mx = S.base * Math.pow(S.ratio, s); return [mn, mx]; }
