.acr-board {
  /* re-theme with these four (plus the guide colour) */
  --acr-board-bg: oklch(0.968 0.006 80);
  --acr-board-surface: oklch(0.994 0.003 80);
  --acr-board-ink: oklch(0.24 0.012 60);
  --acr-board-accent: oklch(0.58 0.12 195);
  --acr-board-guide: oklch(0.63 0.23 352);
  /* derived */
  --acr-board-line: color-mix(in oklch, var(--acr-board-ink) 10%, transparent);
  --acr-board-line2: color-mix(in oklch, var(--acr-board-ink) 18%, transparent);
  --acr-board-hover: color-mix(in oklch, var(--acr-board-ink) 5%, transparent);
  --acr-board-mute: color-mix(in oklch, var(--acr-board-ink) 64%, var(--acr-board-bg));
  --acr-board-faint: color-mix(in oklch, var(--acr-board-ink) 42%, var(--acr-board-bg));
  --acr-board-acc-soft: color-mix(in oklch, var(--acr-board-accent) 12%, var(--acr-board-surface));
  --acr-board-ease: cubic-bezier(.2, .8, .2, 1);
  --acr-board-out: cubic-bezier(.16, 1, .3, 1);
  --acr-board-spring: linear(0, 0.12 6%, 0.46 14%, 0.86 24%, 1.04 32%, 1.07 38%, 1.03 48%, 0.996 62%, 1);
  --acr-board-mono: ui-monospace, Menlo, monospace;

  position: relative; width: 100%; height: var(--acr-board-h, 680px); box-sizing: border-box;
  container-type: inline-size; container-name: acr-board; overflow: clip; isolation: isolate;
  display: grid; grid-template-rows: auto minmax(0, 1fr) auto;
  border-radius: 16px; background: var(--acr-board-bg); color: var(--acr-board-ink); color-scheme: light;
  accent-color: var(--acr-board-accent); box-shadow: inset 0 0 0 1px var(--acr-board-line);
  font: 12.5px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--acr-board-accent); outline-offset: 2px; }
  & button, & input { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & button:disabled { cursor: not-allowed; opacity: .38; }
  & h3, & p, & ol { margin: 0; padding: 0; }
  & ol { list-style: none; }
  & [hidden] { display: none !important; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { display: inline-grid; place-items: center; min-width: 16px; height: 16px; padding: 0 4px; border-radius: 4px; font: 600 9.5px/1 var(--acr-board-mono); color: var(--acr-board-mute); background: var(--acr-board-surface); box-shadow: inset 0 0 0 1px var(--acr-board-line2); }
  & h3 { display: flex; align-items: center; gap: 8px; font-size: 10.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--acr-board-faint);
    & span { margin-left: auto; font-weight: 500; letter-spacing: 0; text-transform: none; font-variant-numeric: tabular-nums; }
  }
}

/* ── top ─────────────────────────────────────────────── */
.acr-board .acr-board-top { display: flex; align-items: center; gap: 14px; padding: 10px 12px 10px 16px; border-bottom: 1px solid var(--acr-board-line); background: var(--acr-board-surface); min-width: 0; }
.acr-board .acr-board-brand { display: flex; align-items: center; gap: 8px; font-weight: 780; font-size: 14px; & svg { width: 20px; height: 20px; color: var(--acr-board-accent); } }
.acr-board .acr-board-title { display: grid; padding-left: 14px; border-left: 1px solid var(--acr-board-line); min-width: 0; line-height: 1.25;
  & b { font-weight: 650; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & span { font-size: 11px; color: var(--acr-board-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.acr-board .acr-board-tools { margin-left: auto; display: flex; gap: 2px; padding: 2px; border-radius: 10px; background: var(--acr-board-hover);
  & button { display: grid; place-items: center; width: 34px; height: 30px; border-radius: 8px; color: var(--acr-board-mute); transition: background-color .15s, color .15s; }
  & button:hover { color: var(--acr-board-ink); }
