.acr-board .acr-board-libhint { padding: 8px 12px 10px; font-size: 11px; color: var(--acr-board-faint); border-top: 1px solid var(--acr-board-line); text-wrap: pretty; }

.acr-board .acr-board-stage { grid-area: stage; position: relative; min-width: 0; min-height: 0; display: grid; }
.acr-board .acr-board-viewport { position: relative; overflow: hidden; touch-action: none; cursor: default;
  background-color: var(--acr-board-bg);
  background-image: radial-gradient(circle, color-mix(in oklch, var(--acr-board-ink) 16%, transparent) 1px, transparent 1.4px);
  background-size: var(--gs, 18px) var(--gs, 18px); background-position: var(--gx, 0) var(--gy, 0);
}
