.acr-board .acr-board-grip { position: absolute; right: calc(-6px / var(--z, 1)); bottom: calc(-6px / var(--z, 1)); width: calc(12px / var(--z, 1)); height: calc(12px / var(--z, 1)); border-radius: calc(3px / var(--z, 1));
