.acr-board .acr-board-side { grid-area: side; min-height: 0; overflow-y: auto; overscroll-behavior: contain; scrollbar-width: thin; border-left: 1px solid var(--acr-board-line); background: var(--acr-board-surface); }
.acr-board .acr-board-sec { padding: 12px 14px 14px; border-bottom: 1px solid var(--acr-board-line); display: grid; gap: 10px; }
.acr-board .acr-board-selname { display: flex; align-items: center; gap: 8px; font-weight: 650; font-size: 13px; & i { width: 14px; height: 14px; border-radius: 4px; background: var(--c, var(--acr-board-line2)); } }
.acr-board .acr-board-empty { font-size: 12px; color: var(--acr-board-faint); text-wrap: pretty; }
