  .acr-board:not([data-view="lib"]) .acr-board-lib { display: none; }
  .acr-board[data-view="lib"] .acr-board-side { display: none; }
  .acr-board .acr-board-mnav { display: flex; }
  .acr-board .acr-board-mnav [data-v="board"] { display: none; }
  .acr-board .acr-board-title span { display: none; }
}
@container acr-board (max-width: 759px) {
  .acr-board .acr-board-body { grid-template-columns: minmax(0, 1fr); grid-template-areas: "main"; }
  .acr-board .acr-board-stage, .acr-board .acr-board-lib, .acr-board .acr-board-side { grid-area: main; border: 0; }
  .acr-board:not([data-view="board"]) .acr-board-stage { display: none; }
