  .acr-board .acr-board-mnav [data-v="board"] { display: block; }
  .acr-board .acr-board-title { display: none; }
  .acr-board .acr-board-libgrid { grid-template-columns: repeat(auto-fill, minmax(96px, 1fr)); }
}
@container acr-board (max-width: 480px) {
  .acr-board .acr-board-top { gap: 6px; padding-left: 12px; }
  .acr-board .acr-board-brand span, .acr-board .acr-board-primary span { display: none; }
  .acr-board .acr-board-primary { padding: 0 9px; }
  .acr-board .acr-board-acts { gap: 2px; }
  .acr-board .acr-board-tools button { width: 30px; }
}

@media (prefers-reduced-motion: reduce) {
  .acr-board *, .acr-board *::before, .acr-board *::after { animation-duration: 1ms !important; animation-delay: 0ms !important; transition-duration: 1ms !important; }
}

