/* ── Pinwall · mood board with smart guides ────────────────────────────
   Cards live in world coordinates inside one transformed layer
   (translate + scale), so pan and zoom are a single transform and the
   dot grid follows by moving its background. While a selection is
   dragged its bounding box is compared with every other card's edges
   and centres; the nearest match inside six screen pixels snaps it and
   draws a guide, and the nearest neighbours on each axis get a live
   gap measurement. Guides and the marquee are drawn in screen space so
   they stay one pixel thick at any zoom. */
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const clamp = (v, a, b) => v < a ? a : v > b ? b : v;
const esc = s => String(s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');

const ART = { kiln: ['Kiln at dusk', 'Firing no. 118'], tide: ['Tidepool', 'Saltmarsh Point, low tide'], linen: ['Linen weave', 'Tablecloth sample L-04'], glaze: ['Glaze drip', 'Celadon over iron'], harbour: ['Harbour, 6 am', 'First light from the jetty'], dune: ['Dune grass', 'Marram on the north dune'] };
