/* ── geometry helpers ──────────────────────────────── */
function bbox(list) { const x = Math.min(...list.map(i => i.x)), y = Math.min(...list.map(i => i.y)), r = Math.max(...list.map(i => i.x + i.w)), b = Math.max(...list.map(i => i.y + i.h)); return { x, y, w: r - x, h: b - y }; }
const toWorld = (cx, cy) => { const r = vp.getBoundingClientRect(); return { x: (cx - r.left - S.view.x) / S.view.z, y: (cy - r.top - S.view.y) / S.view.z }; };
const toScreen = (x, y) => ({ x: x * S.view.z + S.view.x, y: y * S.view.z + S.view.y });
function snapBox(b, moving) {
  const T = 6 / S.view.z, others = items.filter(i => !moving.has(i.id));
  const mx = [b.x, b.x + b.w / 2, b.x + b.w], my = [b.y, b.y + b.h / 2, b.y + b.h];
  let bx = null, by = null;
  others.forEach(o => {
    const ox = [o.x, o.x + o.w / 2, o.x + o.w], oy = [o.y, o.y + o.h / 2, o.y + o.h];
    for (let i = 0; i < 3; i++) for (let j = 0; j < 3; j++) {
