    const gapV = (y0, y1, x) => { const p = toScreen(x, y0), q = toScreen(x, y1); if (q.y - p.y < 14) return ''; return '<i class="acr-board-gl is-v" style="left:' + Math.round(p.x) + 'px;top:' + p.y + 'px;height:' + (q.y - p.y) + 'px;opacity:.6"></i><span class="acr-board-badge is-guide" style="left:' + (p.x + 22) + 'px;top:' + ((p.y + q.y) / 2 - 9) + 'px">' + Math.round(y1 - y0) + '</span>'; };
