    overlay.innerHTML = '<i class="acr-board-marq" style="left:' + x0 + 'px;top:' + y0 + 'px;width:' + (x1 - x0) + 'px;height:' + (y1 - y0) + 'px"></i>' + (hit.length ? '<span class="acr-board-badge" style="left:' + (x0 + x1) / 2 + 'px;top:' + (y1 + 8) + 'px">' + hit.length + ' selected</span>' : '');
  }
});
const endAct = () => {
  if (!act) return;
  const a = act; act = null; overlay.innerHTML = ''; vp.classList.remove('is-panning');
  $$('.is-drag', world).forEach(el => el.classList.remove('is-drag'));
  if (a.type === 'move') { if (a.moved) { commit(); renderSide(); } else if (a.clickId && S.sel.size > 1) select([a.clickId]); }
  else if (a.type === 'resize' && a.moved) { commit(); renderSide(); }
  else if (a.type === 'marquee') renderSide();
};
vp.addEventListener('pointerup', endAct); vp.addEventListener('pointercancel', endAct);
vp.addEventListener('wheel', e => {
  e.preventDefault();
  if (e.ctrlKey || e.metaKey) { const r = vp.getBoundingClientRect(); zoomAt(S.view.z * Math.exp(-e.deltaY * .01), e.clientX - r.left, e.clientY - r.top); }
  else { S.view.x -= e.deltaX; S.view.y -= e.deltaY; S.fitted = false; applyView(); }
}, { passive: false });
vp.addEventListener('dblclick', e => { const card = e.target.closest('.acr-board-card'); if (card) { const it = items.find(i => i.id === card.dataset.id); if (it && it.kind === 'note') startEdit(it.id); } });

function zoomAt(z, px, py, anim) {
  z = clamp(z, .25, 2); const k = z / S.view.z;
  S.view.x = px - (px - S.view.x) * k; S.view.y = py - (py - S.view.y) * k; S.view.z = z; S.fitted = false; applyView(anim);
}
function fit(anim) {
  if (!items.length) return;
  const b = bbox(items), w = vp.clientWidth, h = vp.clientHeight, pad = 36;
  const z = clamp(Math.min((w - pad * 2) / b.w, (h - pad * 2 - 30) / b.h), .25, 1.5);
  S.view = { z, x: (w - b.w * z) / 2 - b.x * z, y: (h - 30 - b.h * z) / 2 - b.y * z }; S.fitted = true; applyView(anim);
}

/* ── notes editing ─────────────────────────────────── */
function startEdit(id) {
  const el = world.querySelector('[data-id="' + id + '"] [data-text]'); if (!el) return;
  S.edit = id; el.contentEditable = 'true'; el.focus();
  const r = document.createRange(); r.selectNodeContents(el); const s = getSelection(); s.removeAllRanges(); s.addRange(r);
}
function endEdit() {
  const id = S.edit; if (!id) return; S.edit = null;
  const el = world.querySelector('[data-id="' + id + '"] [data-text]'), it = items.find(i => i.id === id);
  if (el) { el.contentEditable = 'false'; const t = el.textContent.trim(); if (it && t && t !== it.d.text) { it.d.text = t; commit(); toast('Note updated'); } else if (it) el.textContent = it.d.text; }
  renderSide();
}
world.addEventListener('focusout', e => { if (S.edit && e.target.matches('[data-text]')) endEdit(); });

/* ── library ───────────────────────────────────────── */
function renderLib() {
  const box = $('[data-lib]');
  if (S.lt === 'img') box.innerHTML = Object.entries(ART).map(([k, [n]], i) => '<button class="acr-board-libitem" data-add="img" data-key="' + k + '" style="--i:' + i + '" title="Add ' + n + '"><span class="acr-board-thumb acr-board-a-' + k + '"></span>' + n + '</button>').join('');
  else if (S.lt === 'color') box.innerHTML = COLORS.map(([n, h], i) => '<button class="acr-board-libitem" data-add="swatch" data-key="' + i + '" style="--i:' + i + '" title="Add ' + n + ' ' + h + '"><span class="acr-board-thumb" style="background:' + h + '"></span>' + n + '</button>').join('');
  else box.innerHTML = NOTES.map(([n, c], i) => '<button class="acr-board-libitem" data-add="note" data-key="' + i + '" style="--i:' + i + '" title="Add a ' + n.toLowerCase() + '"><span class="acr-board-thumb" style="background:' + c + '"></span>' + n + '</button>').join('') +
    '<button class="acr-board-libitem is-wide" data-add="type" data-key="0" style="--i:3" title="Add a type card"><span class="acr-board-thumb" style="background:oklch(0.97 0.01 85);display:grid;place-items:center;font:400 34px Georgia,serif">Aa</span>Type card</button>' +
    '<button class="acr-board-libitem is-wide" data-add="quote" data-key="0" style="--i:4" title="Add a quote card"><span class="acr-board-thumb" style="background:oklch(0.27 0.02 60);color:oklch(0.95 0.01 85);display:grid;place-items:center;font:italic 18px Georgia,serif">“Found, then fired.”</span>Quote card</button>';
}
function addItem(kind, key, pt) {
  const size = { img: [240, 180], swatch: [110, 110], note: [200, 160], type: [214, 214], quote: [260, 170] }[kind];
  const d = kind === 'img' ? { art: key } : kind === 'swatch' ? { name: COLORS[key][0], hex: COLORS[key][1] } : kind === 'note' ? { text: 'New note — double-click to write.', c: NOTES[key][1], by: 'You' } : kind === 'quote' ? { text: '“Found on the beach, then fired.”', by: 'Studio brief, March' } : {};
  if (!pt) { const r = vp.getBoundingClientRect(); pt = toWorld(r.left + r.width / 2, r.top + r.height / 2); pt.x += (items.length % 4) * 14; pt.y += (items.length % 4) * 14; }
  const it = mk(kind, Math.round(pt.x - size[0] / 2), Math.round(pt.y - size[1] / 2), size[0], size[1], d);
  items.push(it); S.sel = new Set([it.id]); S.fitted = false; applyView(); render(); commit();
  const el = world.querySelector('[data-id="' + it.id + '"]'); if (el && !RM.matches) { el.classList.add('is-new'); setTimeout(() => el.classList.remove('is-new'), 600); }
  toast('Added ' + nameOf(it));
  if (kind === 'note') setTimeout(() => { if (root.isConnected) startEdit(it.id); }, 60);
  return it;
}
/* drag from the library onto the board */
let libDrag = null;
$('[data-lib]').addEventListener('pointerdown', e => {
  const b = e.target.closest('[data-add]'); if (!b || e.button !== 0) return;
  libDrag = { b, sx: e.clientX, sy: e.clientY, ghost: null, moved: false };
  b.setPointerCapture(e.pointerId);
});
$('[data-lib]').addEventListener('pointermove', e => {
  if (!libDrag) return;
  if (!libDrag.moved && Math.hypot(e.clientX - libDrag.sx, e.clientY - libDrag.sy) < 5) return;
  const rr = root.getBoundingClientRect();
  if (!libDrag.ghost) { libDrag.moved = true; const g = document.createElement('div'); g.className = 'acr-board-ghost'; g.style.background = getComputedStyle(libDrag.b.querySelector('.acr-board-thumb')).background; root.appendChild(g); libDrag.ghost = g; }
  libDrag.ghost.style.left = e.clientX - rr.left + 'px'; libDrag.ghost.style.top = e.clientY - rr.top + 'px';
});
const endLib = e => {
  if (!libDrag) return;
  const d = libDrag; libDrag = null;
  if (d.ghost) {
    d.ghost.remove(); const r = vp.getBoundingClientRect();
    if (e.type === 'pointerup' && e.clientX > r.left && e.clientX < r.right && e.clientY > r.top && e.clientY < r.bottom) addItem(d.b.dataset.add, d.b.dataset.add === 'img' ? d.b.dataset.key : +d.b.dataset.key, toWorld(e.clientX, e.clientY));
    else toast('Drop onto the board to add it');
    d.b.dataset.dragged = '1';
  }
};
$('[data-lib]').addEventListener('pointerup', endLib); $('[data-lib]').addEventListener('pointercancel', endLib);

/* ── commands ──────────────────────────────────────── */
const selected = () => items.filter(i => S.sel.has(i.id));
function del() { const n = S.sel.size; if (!n) return; items = items.filter(i => !S.sel.has(i.id)); S.sel.clear(); render(); commit(); toast('Deleted ' + n + (n === 1 ? ' card' : ' cards') + ' — ⌘Z to restore'); }
function dup() {
  const sel = selected(); if (!sel.length) return;
  const copies = sel.map(i => Object.assign(JSON.parse(JSON.stringify(i)), { id: 'c' + (++nid), x: i.x + 24, y: i.y + 24 }));
  items.push(...copies); S.sel = new Set(copies.map(c => c.id)); render(); commit(); toast('Duplicated ' + copies.length + (copies.length === 1 ? ' card' : ' cards'));
}
function order(kind) {
  const sel = selected(); if (!sel.length) return;
  const rest = items.filter(i => !S.sel.has(i.id));
  if (kind === 'front') items = rest.concat(sel);
  else if (kind === 'bottom') items = sel.concat(rest);
  else {
    const step = kind === 'fwd' ? 1 : -1, idx = sel.map(s => items.indexOf(s)).sort((a, b) => step > 0 ? b - a : a - b);
    idx.forEach(i => { const j = i + step; if (j >= 0 && j < items.length && !S.sel.has(items[j].id)) [items[i], items[j]] = [items[j], items[i]]; });
  }
  render(); commit(); toast({ front: 'Brought to front', bottom: 'Sent to back', fwd: 'Brought forward', back: 'Sent backward' }[kind]);
}
function align(k) {
  const sel = selected(), b = bbox(sel);
  sel.forEach(i => { if (k === 'l') i.x = b.x; if (k === 'r') i.x = b.x + b.w - i.w; if (k === 'c') i.x = Math.round(b.x + b.w / 2 - i.w / 2); if (k === 't') i.y = b.y; if (k === 'b') i.y = b.y + b.h - i.h; if (k === 'm') i.y = Math.round(b.y + b.h / 2 - i.h / 2); });
  animateMove(sel); render(); commit(); toast('Aligned ' + sel.length + ' cards');
}
function distribute(axis) {
  const sel = selected().sort((a, b) => axis === 'h' ? a.x - b.x : a.y - b.y), b = bbox(sel);
  const total = sel.reduce((n, i) => n + (axis === 'h' ? i.w : i.h), 0), gap = ((axis === 'h' ? b.w : b.h) - total) / (sel.length - 1);
  let p = axis === 'h' ? b.x : b.y; sel.forEach(i => { if (axis === 'h') i.x = Math.round(p); else i.y = Math.round(p); p += (axis === 'h' ? i.w : i.h) + gap; });
  animateMove(sel); render(); commit(); toast('Equal ' + Math.round(gap) + 'px gaps');
}
function animateMove(list) {
  if (RM.matches) return;
  list.forEach(i => { const el = world.querySelector('[data-id="' + i.id + '"]'); if (!el) return; const ox = parseFloat(el.style.left), oy = parseFloat(el.style.top); el.animate([{ transform: 'translate(' + (ox - i.x) + 'px,' + (oy - i.y) + 'px)' }, { transform: 'none' }], { duration: 380, easing: 'cubic-bezier(.16,1,.3,1)' }); });
}
function nudge(dx, dy) { const sel = selected(); if (!sel.length) return; sel.forEach(i => { i.x += dx; i.y += dy; }); renderCards(); clearTimeout(nudge.t); nudge.t = setTimeout(() => { if (!root.isConnected) return; commit(); renderSide(); }, 350); }
function setTool(t) { S.tool = t; root.dataset.tool = t; $$('.acr-board-tools [data-tool]').forEach(b => b.setAttribute('aria-checked', b.dataset.tool === t)); }
function setView(v) { root.dataset.view = v; $$('.acr-board-mnav [data-v]').forEach(b => b.setAttribute('aria-selected', b.dataset.v === v)); }

root.addEventListener('click', e => {
  const t = e.target.closest('button'); if (!t || !root.contains(t) || t.disabled) return;
  const a = t.dataset.act, r = vp.getBoundingClientRect();
  if (t.dataset.add) { if (t.dataset.dragged) { delete t.dataset.dragged; return; } addItem(t.dataset.add, t.dataset.add === 'img' ? t.dataset.key : +t.dataset.key); if (root.clientWidth < 760) setView('board'); return; }
  if (a === 'undo') { if (hi > 0) { restore(hi - 1); toast('Undone'); } }
  else if (a === 'redo') { if (hi < hist.length - 1) { restore(hi + 1); toast('Redone'); } }
  else if (a === 'share') { const url = '/boards/saltmarsh-spring-lookbook'; try { const p = navigator.clipboard && navigator.clipboard.writeText(url); if (p && p.catch) p.catch(() => {}); } catch (err) {} toast('Link copied — ' + url); }
  else if (a === 'zin' || a === 'zout') zoomAt(S.view.z * (a === 'zin' ? 1.25 : .8), r.width / 2, r.height / 2, true);
  else if (a === 'z100') zoomAt(1, r.width / 2, r.height / 2, true);
  else if (a === 'fit') fit(true);
  else if (a === 'del') del();
  else if (a === 'dup') dup();
  else if (t.dataset.tool) setTool(t.dataset.tool);
  else if (t.dataset.lt) { S.lt = t.dataset.lt; $$('[data-lt]').forEach(b => b.setAttribute('aria-selected', b === t)); renderLib(); }
  else if (t.dataset.align) align(t.dataset.align);
  else if (t.dataset.dist) distribute(t.dataset.dist);
  else if (t.dataset.order) order(t.dataset.order);
  else if (t.dataset.pick) { const id = t.dataset.pick; if (e.shiftKey) { S.sel.has(id) ? S.sel.delete(id) : S.sel.add(id); render(); } else select([id]); }
  else if (t.dataset.v) setView(t.dataset.v);
});
root.addEventListener('change', e => {
  const k = e.target.dataset && e.target.dataset.geo; if (!k) return;
  const sel = selected(), v = Math.round(+e.target.value); if (!sel.length || !isFinite(v)) return;
  if (sel.length === 1) { const it = sel[0]; it[k] = (k === 'w' || k === 'h') ? Math.max(48, v) : v; }
  else { const b = bbox(sel), d = v - b[k]; sel.forEach(i => { i[k] += d; }); }
  render(); commit();
});

/* ── keyboard ──────────────────────────────────────── */
root.addEventListener('pointerdown', e => { if (!root.contains(document.activeElement) && !e.target.closest('input, [contenteditable="true"]')) root.focus({ preventScroll: true }); });
root.addEventListener('keydown', e => {
  const t = e.target, mod = e.metaKey || e.ctrlKey, k = e.key.toLowerCase();
  if (S.edit) { if (e.key === 'Escape') { e.preventDefault(); endEdit(); world.querySelector('[data-id="' + [...S.sel][0] + '"]')?.focus(); } return; }
  if (t.matches('input')) { if (e.key === 'Enter') t.blur(); return; }
  if (mod && k === 'z') { e.preventDefault(); $('[data-act="' + (e.shiftKey ? 'redo' : 'undo') + '"]').click(); return; }
  if (mod && k === 'd') { e.preventDefault(); dup(); return; }
  if (mod && k === 'a') { e.preventDefault(); select(items.map(i => i.id)); return; }
  if (mod) return;
  const card = t.closest && t.closest('.acr-board-card');
  if (card && (e.key === 'Enter' || e.key === ' ')) { e.preventDefault(); const it = items.find(i => i.id === card.dataset.id); if (S.sel.has(it.id) && it.kind === 'note' && e.key === 'Enter') startEdit(it.id); else select([it.id], e.shiftKey); return; }
  const tabs = t.closest('[role="tablist"], [role="radiogroup"], [role="listbox"]');
  if (tabs && /^Arrow/.test(e.key) && !S.sel.size) { const it = $$('[role="tab"], [role="radio"], [role="option"]', tabs).filter(x => x.offsetParent), i = it.indexOf(t); if (i >= 0) { e.preventDefault(); const n = it[clamp(i + (/Right|Down/.test(e.key) ? 1 : -1), 0, it.length - 1)]; n.focus(); n.click(); } return; }
  const mv = { ArrowLeft: [-1, 0], ArrowRight: [1, 0], ArrowUp: [0, -1], ArrowDown: [0, 1] }[e.key];
  if (mv && S.sel.size) { e.preventDefault(); const s = e.shiftKey ? 10 : 1; nudge(mv[0] * s, mv[1] * s); return; }
  if ((e.key === 'Delete' || e.key === 'Backspace') && S.sel.size) { e.preventDefault(); del(); return; }
  if (e.key === 'Escape') { if (S.sel.size) { S.sel.clear(); render(); } setTool('select'); return; }
  if (e.key === ']') { e.preventDefault(); order(e.shiftKey ? 'front' : 'fwd'); return; }
  if (e.key === '[') { e.preventDefault(); order(e.shiftKey ? 'bottom' : 'back'); return; }
  if (e.key === ' ' && !t.closest('button')) { e.preventDefault(); if (!spaceDown) { spaceDown = true; vp.classList.add('is-panning'); } return; }
  if (t.closest('button')) return;
  if (k === 'v') setTool('select'); else if (k === 'h') setTool('hand'); else if (k === 'n') setTool('note');
  else if (e.key === '+' || e.key === '=') $('[data-act="zin"]').click(); else if (e.key === '-') $('[data-act="zout"]').click();
  else if (e.key === '0') zoomAt(1, vp.clientWidth / 2, vp.clientHeight / 2, true); else if (e.key === '!') fit(true);
});
root.addEventListener('keyup', e => { if (e.key === ' ' && spaceDown) { spaceDown = false; vp.classList.remove('is-panning'); } });

/* ── layout ────────────────────────────────────────── */
let first = true, lastW = 0;
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  const w = vp.clientWidth; if (!w) return;
  if (first || (S.fitted && Math.abs(w - lastW) > 2)) { fit(false); first = false; }
  lastW = w;
  const rw = root.clientWidth; if (rw >= 760 && rw < 960 && root.dataset.view === 'board') setView('side');
});
ro.observe(vp); ro.observe(root);

renderLib(); render(); applyView(); commit();

