.acr-pen {
  /* re-theme with these four */
  --acr-pen-bg: oklch(0.2 0.014 165);
  --acr-pen-panel: oklch(0.236 0.015 165);
  --acr-pen-ink: oklch(0.94 0.012 120);
  --acr-pen-accent: oklch(0.88 0.17 124);
  /* derived */
  --acr-pen-line: color-mix(in oklch, var(--acr-pen-ink) 9%, transparent);
  --acr-pen-line2: color-mix(in oklch, var(--acr-pen-ink) 16%, transparent);
  --acr-pen-hover: color-mix(in oklch, var(--acr-pen-ink) 6%, transparent);
  --acr-pen-mute: color-mix(in oklch, var(--acr-pen-ink) 64%, var(--acr-pen-bg));
  --acr-pen-faint: color-mix(in oklch, var(--acr-pen-ink) 40%, var(--acr-pen-bg));
  --acr-pen-acc-soft: color-mix(in oklch, var(--acr-pen-accent) 14%, transparent);
  --acr-pen-acc-ink: oklch(0.22 0.04 130);
  --acr-pen-sel: oklch(0.62 0.2 255);
  --acr-pen-ease: cubic-bezier(.2, .8, .2, 1);
  --acr-pen-out: cubic-bezier(.16, 1, .3, 1);
  --acr-pen-spring: linear(0, 0.12 6%, 0.46 14%, 0.86 24%, 1.04 32%, 1.07 38%, 1.03 48%, 0.996 62%, 1);
  --acr-pen-mono: ui-monospace, Menlo, monospace;

  position: relative; width: 100%; height: var(--acr-pen-h, 680px); box-sizing: border-box;
  container-type: inline-size; container-name: acr-pen; overflow: clip; isolation: isolate;
  display: grid; grid-template-rows: auto minmax(0, 1fr) auto;
  border-radius: 16px; background: var(--acr-pen-bg); color: var(--acr-pen-ink); color-scheme: dark; accent-color: var(--acr-pen-accent);
  font: 12.5px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; -webkit-font-smoothing: antialiased; -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--acr-pen-accent); outline-offset: 2px; }
  & button, & input { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & button:disabled { cursor: not-allowed; opacity: .35; }
  & h2, & h3, & p, & ol { margin: 0; padding: 0; }
  & ol { list-style: none; }
  & [hidden] { display: none !important; }
  & :is(header, nav, aside, footer) svg, & .acr-pen-dlg svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { display: inline-grid; place-items: center; min-width: 14px; height: 14px; padding: 0 3px; border-radius: 3px; font: 600 9px/1 var(--acr-pen-mono); }
  & h3 { display: flex; align-items: center; gap: 8px; min-height: 24px; font-size: 10.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--acr-pen-faint);
    & > span:not(.acr-pen-hacts) { margin-left: auto; font-weight: 500; letter-spacing: 0; text-transform: none; color: var(--acr-pen-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  }
}

/* ── top ─────────────────────────────────────────────── */
.acr-pen .acr-pen-top { display: flex; align-items: center; gap: 14px; padding: 10px 12px 10px 16px; border-bottom: 1px solid var(--acr-pen-line); min-width: 0; }
.acr-pen .acr-pen-brand { display: flex; align-items: center; gap: 8px; font-weight: 780; font-size: 14px; letter-spacing: .01em; & svg { width: 20px; height: 20px; color: var(--acr-pen-accent); } }
.acr-pen .acr-pen-file { display: flex; align-items: baseline; gap: 10px; padding-left: 14px; border-left: 1px solid var(--acr-pen-line); min-width: 0;
  & b { font: 600 12.5px var(--acr-pen-mono); white-space: nowrap; }
  & span { font-size: 11.5px; color: var(--acr-pen-faint); white-space: nowrap; font-variant-numeric: tabular-nums; }
}
.acr-pen .acr-pen-hint { flex: 1; min-width: 0; text-align: center; font-size: 12px; color: var(--acr-pen-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  & b { color: var(--acr-pen-accent); font-weight: 600; }
}
.acr-pen .acr-pen-acts { display: flex; align-items: center; gap: 6px; }
.acr-pen .acr-pen-ib, .acr-pen .acr-pen-mini { display: grid; place-items: center; width: 32px; height: 32px; border-radius: 9px; color: var(--acr-pen-mute); transition: background-color .15s, color .15s, transform .3s var(--acr-pen-spring);
  &:hover:not(:disabled) { background: var(--acr-pen-hover); color: var(--acr-pen-ink); }
  &:active:not(:disabled) { transform: scale(.9); }
}
